from tensorflow.keras import layers

data_augmentation = tf.keras.Sequential([

    layers.RandomRotation(0.1),

    layers.RandomZoom(0.1),

    layers.RandomContrast(0.1),

    layers.RandomTranslation(
        height_factor=0.05,
        width_factor=0.05
    )

])

import matplotlib.pyplot as plt

for images, labels in train_ds.take(1):

    first_image = images[0]

    plt.figure(figsize=(10,10))

    for i in range(9):

        augmented_image = data_augmentation(
            tf.expand_dims(first_image, 0)
        )

        ax = plt.subplot(3,3,i+1)

        plt.imshow(
            augmented_image[0].numpy().astype("uint8")
        )

        plt.axis("off")

    plt.show()

from tensorflow.keras import layers
import tensorflow as tf

data_augmentation = tf.keras.Sequential([

    layers.RandomContrast(0.05),#Heyyy





    layers.RandomTranslation(
        height_factor=0.03,
        width_factor=0.03
    ),



    layers.Lambda(
        lambda x: tf.image.random_brightness(
            x,
            max_delta=0.15
        )
    ),

    layers.Lambda(
        lambda x: tf.image.random_saturation(
            x,
            lower=0.8,
            upper=1.2
        )
    ),

    layers.Lambda(
        lambda x: tf.image.random_hue(
            x,
            max_delta=0.08
        )
    )
])

import matplotlib.pyplot as plt

for images, labels in train_ds.take(1):

    img = images[0]

    plt.figure(figsize=(12,12))

    for i in range(16):

        aug_img = data_augmentation(
            tf.expand_dims(img, 0),
            training=True
        )

        ax = plt.subplot(4,4,i+1)

        plt.imshow(
            aug_img[0].numpy().astype("uint8")
        )

        plt.axis("off")

    plt.show()

from tensorflow.keras import layers, models

model_aug = models.Sequential([

    data_augmentation,

    layers.Rescaling(1./255),

    layers.Conv2D(32, (3,3), activation='relu'),
    layers.MaxPooling2D(),

    layers.Conv2D(64, (3,3), activation='relu'),
    layers.MaxPooling2D(),

    layers.Conv2D(128, (3,3), activation='relu'),
    layers.MaxPooling2D(),

    layers.GlobalAveragePooling2D(),

    layers.Dense(64, activation='relu'),

    layers.Dense(4, activation='softmax')
])

model_aug.compile(
    optimizer='adam',
    loss='sparse_categorical_crossentropy',
    metrics=['accuracy']
)

model_aug.summary()

history_aug = model_aug.fit(
    train_ds,
    validation_data=valid_ds,
    epochs=20
)

