import os
import shutil

source_root = "/content/drive/MyDrive/PCB_AI_Split_Dataset"
destination = "/content/all_labeled_images"

os.makedirs(destination, exist_ok=True)

for split in ["train", "valid", "test"]:
    split_path = os.path.join(source_root, split)

    for class_name in os.listdir(split_path):
        class_path = os.path.join(split_path, class_name)

        if os.path.isdir(class_path):
            for file in os.listdir(class_path):
                src = os.path.join(class_path, file)

                new_name = f"{class_name}_{file}"

                dst = os.path.join(destination, new_name)

                shutil.copy2(src, dst)

print("Done!")
print("Total images:", len(os.listdir(destination)))

