import tensorflow as tf
import numpy as np
import matplotlib.pyplot as plt

class_names = ["Bottom", "Left", "Right", "Top"]

def predict_and_explain(image_path):

    img = tf.keras.utils.load_img(
        image_path,
        target_size=(224,224)
    )

    img_array = tf.keras.utils.img_to_array(img)

    input_arr = np.expand_dims(img_array, axis=0)

    predictions = model.predict(input_arr, verbose=0)

    probs = predictions[0]

    pred_idx = np.argmax(probs)

    pred_class = class_names[pred_idx]

    confidence = probs[pred_idx]

    # Show image
    plt.figure(figsize=(5,5))
    plt.imshow(img)
    plt.axis("off")
    plt.title(
        f"Prediction: {pred_class}\nConfidence: {confidence:.2%}"
    )
    plt.show()

    print("="*50)
    print(f"Prediction : {pred_class}")
    print(f"Confidence : {confidence:.2%}")
    print("="*50)

    print("\nClass Probabilities:")

    sorted_probs = sorted(
        zip(class_names, probs),
        key=lambda x: x[1],
        reverse=True
    )

    for cls, prob in sorted_probs:
        print(f"{cls:8s}: {prob:.2%}")

    top1_prob = sorted_probs[0][1]
    top2_prob = sorted_probs[1][1]

    gap = top1_prob - top2_prob

    print("\nInterpretation:")

    if confidence > 0.85:
        print("The model is highly confident.")
    elif confidence > 0.60:
        print("The model is moderately confident.")
    else:
        print("The model is uncertain.")

    if gap > 0.50:
        print(
            f"It strongly prefers {pred_class} over all other classes."
        )

    elif gap > 0.20:
        print(
            f"It prefers {pred_class}, but another class is also plausible."
        )

    else:
        print(
            f"The model is confused between "
            f"{sorted_probs[0][0]} and {sorted_probs[1][0]}."
        )

