import os
import numpy as np
from PIL import Image, ImageEnhance, ImageOps
import cv2

DATASET_PATH = "/content/Capacitor-Marker-position-Projec-4"  # from your output

# ── SAME AUGMENTATION FUNCTIONS (no invert) ──────────────────────────────────
def aug_hue_shift(img, shift_deg):
    arr = np.array(img.convert("RGB")).astype(np.uint8)
    hsv = cv2.cvtColor(arr, cv2.COLOR_RGB2HSV).astype(np.int32)
    hsv[:, :, 0] = (hsv[:, :, 0] + shift_deg) % 180
    hsv = np.clip(hsv, 0, 255).astype(np.uint8)
    return Image.fromarray(cv2.cvtColor(hsv, cv2.COLOR_HSV2RGB))

def aug_saturation(img, factor):
    return ImageEnhance.Color(img).enhance(factor)

def aug_channel_boost(img, channel, factor):
    arr = np.array(img).astype(np.float32)
    arr[:, :, channel] = np.clip(arr[:, :, channel] * factor, 0, 255)
    return Image.fromarray(arr.astype(np.uint8))

def aug_grayscale(img):
    return ImageOps.grayscale(img).convert("RGB")

def aug_brightness(img, factor):
    return ImageEnhance.Brightness(img).enhance(factor)

def aug_contrast(img, factor):
    return ImageEnhance.Contrast(img).enhance(factor)

def aug_warm_tone(img):
    arr = np.array(img).astype(np.float32)
    arr[:, :, 0] = np.clip(arr[:, :, 0] * 1.3, 0, 255)
    arr[:, :, 2] = np.clip(arr[:, :, 2] * 0.7, 0, 255)
    return Image.fromarray(arr.astype(np.uint8))

def aug_cool_tone(img):
    arr = np.array(img).astype(np.float32)
    arr[:, :, 0] = np.clip(arr[:, :, 0] * 0.7, 0, 255)
    arr[:, :, 2] = np.clip(arr[:, :, 2] * 1.3, 0, 255)
    return Image.fromarray(arr.astype(np.uint8))

def get_all_variants(img):
    return {
        "Hue_p30":       aug_hue_shift(img,  30),
        "Hue_p60":       aug_hue_shift(img,  60),
        "Hue_p90":       aug_hue_shift(img,  90),
        "Hue_p120":      aug_hue_shift(img, 120),
        "Hue_n30":       aug_hue_shift(img, -30),
        "Hue_n60":       aug_hue_shift(img, -60),
        "Sat_High":      aug_saturation(img, 1.8),
        "Sat_Low":       aug_saturation(img, 0.3),
        "Grayscale":     aug_grayscale(img),
        "Red_Cast":      aug_channel_boost(img, 0, 1.6),
        "Green_Cast":    aug_channel_boost(img, 1, 1.6),
        "Blue_Cast":     aug_channel_boost(img, 2, 1.6),
        "Warm_Tone":     aug_warm_tone(img),
        "Cool_Tone":     aug_cool_tone(img),
        "Bright":        aug_brightness(img, 1.4),
        "Dark":          aug_brightness(img, 0.6),
        "Contrast_High": aug_contrast(img, 1.5),
        "Contrast_Low":  aug_contrast(img, 0.5),
    }

# ── AUGMENT KEEPING FOLDER STRUCTURE (labels preserved!) ─────────────────────
out_root = "/content/augmented_labeled"

total_saved = 0

for split in ["train", "valid", "test"]:
    for cls in ["Bottom", "Left", "Right", "Top"]:

        src_folder = f"{DATASET_PATH}/{split}/{cls}"
        dst_folder = f"{out_root}/{split}/{cls}"
        os.makedirs(dst_folder, exist_ok=True)

        if not os.path.exists(src_folder):
            continue

        images = [f for f in os.listdir(src_folder)
                  if f.lower().endswith(('.jpg', '.jpeg', '.png'))]

        for fname in images:
            img = Image.open(
                os.path.join(src_folder, fname)
            ).convert("RGB")
            stem = os.path.splitext(fname)[0]

            # Save original
            img.save(os.path.join(dst_folder, fname), quality=95)
            total_saved += 1

            # Only augment train, not valid/test
            if split == "train":
                for label, aug_img in get_all_variants(img).items():
                    aug_img.save(
                        os.path.join(dst_folder, f"{stem}_{label}.jpg"),
                        quality=95
                    )
                    total_saved += 1

# ── SUMMARY ───────────────────────────────────────────────────────────────────
print("\nFinal dataset breakdown:")
for split in ["train", "valid", "test"]:
    print(f"\n{split.upper()}")
    for cls in ["Bottom", "Left", "Right", "Top"]:
        path = f"{out_root}/{split}/{cls}"
        if os.path.exists(path):
            print(f"  {cls}: {len(os.listdir(path))} images")

print(f"\nTotal images saved: {total_saved}")
print(f"Saved to: {out_root}")

import os
import shutil
import random

src_root = "/content/augmented_labeled"
dst_root = "/content/final_dataset"

random.seed(42)

for cls in ["Bottom", "Left", "Right", "Top"]:

    # Get all train images for this class
    train_folder = f"{src_root}/train/{cls}"
    all_images   = os.listdir(train_folder)
    random.shuffle(all_images)

    total = len(all_images)
    n_test  = int(total * 0.10)   # 10% test
    n_valid = int(total * 0.10)   # 10% valid
    n_train = total - n_test - n_valid  # 80% train

    splits = {
        "train": all_images[:n_train],
        "valid": all_images[n_train:n_train + n_valid],
        "test":  all_images[n_train + n_valid:]
    }

    for split, files in splits.items():
        out_folder = f"{dst_root}/{split}/{cls}"
        os.makedirs(out_folder, exist_ok=True)
        for fname in files:
            shutil.copy(
                os.path.join(train_folder, fname),
                os.path.join(out_folder, fname)
            )

# ── SUMMARY ──────────────────────────────────────────────────────────────────
print("Final balanced dataset:")
for split in ["train", "valid", "test"]:
    print(f"\n{split.upper()}")
    total = 0
    for cls in ["Bottom", "Left", "Right", "Top"]:
        path  = f"{dst_root}/{split}/{cls}"
        count = len(os.listdir(path))
        total += count
        print(f"  {cls}: {count}")
    print(f"  Total: {total}")

import tensorflow as tf
import numpy as np
from tensorflow.keras import layers, models
from tensorflow.keras.callbacks import EarlyStopping, ReduceLROnPlateau, ModelCheckpoint
from sklearn.utils.class_weight import compute_class_weight
from sklearn.metrics import confusion_matrix, classification_report

DATASET_PATH = "/content/final_dataset"
IMG_SIZE     = (224, 224)
BATCH_SIZE   = 32

# ── STEP 1: LOAD DATA ─────────────────────────────────────────────────────────
train_ds = tf.keras.preprocessing.image_dataset_from_directory(
    f"{DATASET_PATH}/train",
    image_size=IMG_SIZE,
    batch_size=BATCH_SIZE,
    shuffle=True
)

valid_ds = tf.keras.preprocessing.image_dataset_from_directory(
    f"{DATASET_PATH}/valid",
    image_size=IMG_SIZE,
    batch_size=BATCH_SIZE,
    shuffle=False
)

test_ds = tf.keras.preprocessing.image_dataset_from_directory(
    f"{DATASET_PATH}/test",
    image_size=IMG_SIZE,
    batch_size=BATCH_SIZE,
    shuffle=False
)

print("Classes:", train_ds.class_names)

# ── STEP 2: CLASS WEIGHTS ─────────────────────────────────────────────────────
labels = []
for _, y in train_ds:
    labels.extend(y.numpy())
labels = np.array(labels)

class_weights = compute_class_weight(
    class_weight="balanced",
    classes=np.unique(labels),
    y=labels
)
class_weights = dict(enumerate(class_weights))
print("Class weights:", class_weights)

# ── STEP 3: BUILD MOBILENETV2 MODEL ──────────────────────────────────────────
base_model = tf.keras.applications.MobileNetV2(
    input_shape=(224, 224, 3),
    include_top=False,
    weights='imagenet'
)
base_model.trainable = False   # freeze first

model = models.Sequential([
    layers.Input(shape=(224, 224, 3)),
    layers.Rescaling(1./127.5, offset=-1),  # MobileNet needs [-1, 1]
    base_model,
    layers.GlobalAveragePooling2D(),
    layers.BatchNormalization(),
    layers.Dense(128, activation='relu'),
    layers.Dropout(0.4),
    layers.Dense(64, activation='relu'),
    layers.Dropout(0.3),
    layers.Dense(4, activation='softmax')
])

model.compile(
    optimizer=tf.keras.optimizers.Adam(1e-3),
    loss='sparse_categorical_crossentropy',
    metrics=['accuracy']
)

model.summary()

# ── STEP 4: PHASE 1 — Train top layers only ───────────────────────────────────
print("\nPhase 1: Training top layers (frozen base)...")

history1 = model.fit(
    train_ds,
    validation_data=valid_ds,
    epochs=10,
    class_weight=class_weights
)

# ── STEP 5: PHASE 2 — Unfreeze and fine-tune ─────────────────────────────────
print("\nPhase 2: Fine-tuning last 40 layers...")

base_model.trainable = True
for layer in base_model.layers[:-40]:
    layer.trainable = False

model.compile(
    optimizer=tf.keras.optimizers.Adam(1e-5),
    loss='sparse_categorical_crossentropy',
    metrics=['accuracy']
)

callbacks = [
    EarlyStopping(
        monitor='val_accuracy',
        patience=6,
        restore_best_weights=True,
        verbose=1
    ),
    ReduceLROnPlateau(
        monitor='val_loss',
        factor=0.5,
        patience=3,
        verbose=1
    ),
    ModelCheckpoint(
        "/content/drive/MyDrive/best_model.keras",
        monitor='val_accuracy',
        save_best_only=True,
        verbose=1
    )
]

history2 = model.fit(
    train_ds,
    validation_data=valid_ds,
    epochs=30,
    class_weight=class_weights,
    callbacks=callbacks
)

# ── STEP 6: EVALUATE ─────────────────────────────────────────────────────────
print("\nEvaluating on test set...")
test_loss, test_acc = model.evaluate(test_ds)
print(f"\nTest Accuracy : {test_acc:.2%}")
print(f"Test Loss     : {test_loss:.4f}")

y_true, y_pred = [], []
for images, lbls in test_ds:
    preds = model.predict(images, verbose=0)
    y_true.extend(lbls.numpy())
    y_pred.extend(np.argmax(preds, axis=1))

print("\nConfusion Matrix:")
print(confusion_matrix(y_true, y_pred))

print("\nClassification Report:")
print(classification_report(
    y_true, y_pred,
    target_names=train_ds.class_names
))

# ── STEP 7: PLOT TRAINING HISTORY ────────────────────────────────────────────
import matplotlib.pyplot as plt

fig, axes = plt.subplots(1, 2, figsize=(14, 5))

# Combine both phases
acc  = history1.history['accuracy']  + history2.history['accuracy']
val  = history1.history['val_accuracy'] + history2.history['val_accuracy']
loss = history1.history['loss'] + history2.history['loss']
v_loss = history1.history['val_loss'] + history2.history['val_loss']

axes[0].plot(acc,   label='Train Accuracy')
axes[0].plot(val,   label='Val Accuracy')
axes[0].axvline(x=10, color='red', linestyle='--', label='Fine-tune start')
axes[0].set_title('Accuracy')
axes[0].legend()

axes[1].plot(loss,   label='Train Loss')
axes[1].plot(v_loss, label='Val Loss')
axes[1].axvline(x=10, color='red', linestyle='--', label='Fine-tune start')
axes[1].set_title('Loss')
axes[1].legend()

plt.tight_layout()
plt.savefig("/content/drive/MyDrive/training_history.png")
plt.show()

import os
import shutil
import random
import numpy as np
from PIL import Image, ImageEnhance, ImageOps
import cv2

random.seed(42)

DATASET_PATH  = "/content/Capacitor-Marker-position-Projec-4"
CLEAN_DATASET = "/content/clean_dataset"

# ── STEP 1: COLLECT ALL ORIGINALS PER CLASS ───────────────────────────────────
print("Step 1: Collecting original images per class...")

original_per_class = {}

for cls in ["Bottom", "Left", "Right", "Top"]:
    all_images = []
    for split in ["train", "valid", "test"]:
        folder = f"{DATASET_PATH}/{split}/{cls}"
        if os.path.exists(folder):
            for f in os.listdir(folder):
                if f.lower().endswith(('.jpg','.jpeg','.png')):
                    all_images.append((f, folder))

    random.shuffle(all_images)
    original_per_class[cls] = all_images
    print(f"  {cls}: {len(all_images)} original images")

# ── STEP 2: SPLIT ORIGINALS 70/15/15 ─────────────────────────────────────────
print("\nStep 2: Splitting originals 70% train / 15% valid / 15% test...")

split_data = {}

for cls, images in original_per_class.items():
    total   = len(images)
    n_test  = int(total * 0.15)
    n_valid = int(total * 0.15)
    n_train = total - n_test - n_valid

    split_data[cls] = {
        "train": images[:n_train],
        "valid": images[n_train:n_train+n_valid],
        "test":  images[n_train+n_valid:]
    }

    print(f"  {cls}: {n_train} train | {n_valid} valid | {n_test} test")

# ── STEP 3: COPY VALID AND TEST AS ORIGINALS ONLY ────────────────────────────
print("\nStep 3: Saving valid and test (originals only, no augmentation)...")

for cls in ["Bottom", "Left", "Right", "Top"]:
    for split in ["valid", "test"]:
        out = f"{CLEAN_DATASET}/{split}/{cls}"
        os.makedirs(out, exist_ok=True)
        for fname, src_folder in split_data[cls][split]:
            shutil.copy(
                os.path.join(src_folder, fname),
                os.path.join(out, fname)
            )

# ── STEP 4: AUGMENTATION FUNCTIONS ───────────────────────────────────────────
def aug_hue_shift(img, shift_deg):
    arr = np.array(img.convert("RGB")).astype(np.uint8)
    hsv = cv2.cvtColor(arr, cv2.COLOR_RGB2HSV).astype(np.int32)
    hsv[:, :, 0] = (hsv[:, :, 0] + shift_deg) % 180
    hsv = np.clip(hsv, 0, 255).astype(np.uint8)
    return Image.fromarray(cv2.cvtColor(hsv, cv2.COLOR_HSV2RGB))

def get_variants(img):
    arr = np.array(img).astype(np.float32)

    def channel_boost(ch, factor):
        a = arr.copy()
        a[:,:,ch] = np.clip(a[:,:,ch] * factor, 0, 255)
        return Image.fromarray(a.astype(np.uint8))

    def warm(i):
        a = arr.copy()
        a[:,:,0] = np.clip(a[:,:,0] * 1.3, 0, 255)
        a[:,:,2] = np.clip(a[:,:,2] * 0.7, 0, 255)
        return Image.fromarray(a.astype(np.uint8))

    def cool(i):
        a = arr.copy()
        a[:,:,0] = np.clip(a[:,:,0] * 0.7, 0, 255)
        a[:,:,2] = np.clip(a[:,:,2] * 1.3, 0, 255)
        return Image.fromarray(a.astype(np.uint8))

    return {
        "Hue_p30":       aug_hue_shift(img,  30),
        "Hue_p60":       aug_hue_shift(img,  60),
        "Hue_p90":       aug_hue_shift(img,  90),
        "Hue_p120":      aug_hue_shift(img, 120),
        "Hue_n30":       aug_hue_shift(img, -30),
        "Hue_n60":       aug_hue_shift(img, -60),
        "Sat_High":      ImageEnhance.Color(img).enhance(1.8),
        "Sat_Low":       ImageEnhance.Color(img).enhance(0.3),
        "Grayscale":     ImageOps.grayscale(img).convert("RGB"),
        "Red_Cast":      channel_boost(0, 1.6),
        "Green_Cast":    channel_boost(1, 1.6),
        "Blue_Cast":     channel_boost(2, 1.6),
        "Warm_Tone":     warm(img),
        "Cool_Tone":     cool(img),
        "Bright":        ImageEnhance.Brightness(img).enhance(1.4),
        "Dark":          ImageEnhance.Brightness(img).enhance(0.6),
        "Contrast_High": ImageEnhance.Contrast(img).enhance(1.5),
        "Contrast_Low":  ImageEnhance.Contrast(img).enhance(0.5),
    }

# ── STEP 5: AUGMENT TRAIN ONLY ────────────────────────────────────────────────
print("\nStep 4: Augmenting train images only...")

for cls in ["Bottom", "Left", "Right", "Top"]:
    out = f"{CLEAN_DATASET}/train/{cls}"
    os.makedirs(out, exist_ok=True)

    for fname, src_folder in split_data[cls]["train"]:
        img  = Image.open(os.path.join(src_folder, fname)).convert("RGB")
        stem = os.path.splitext(fname)[0]

        # Save original
        img.save(os.path.join(out, fname), quality=95)

        # Save all augmented versions
        for label, aug_img in get_variants(img).items():
            aug_img.save(
                os.path.join(out, f"{stem}_{label}.jpg"),
                quality=95
            )

# ── SUMMARY ───────────────────────────────────────────────────────────────────
print("\n✅ Clean dataset ready!")
print("\nFinal counts:")
for split in ["train", "valid", "test"]:
    print(f"\n{split.upper()}")
    total = 0
    for cls in ["Bottom", "Left", "Right", "Top"]:
        path  = f"{CLEAN_DATASET}/{split}/{cls}"
        count = len(os.listdir(path))
        total += count
        print(f"  {cls}: {count} images")
    print(f"  Total: {total}")

print("\nNo leakage confirmation:")
print("  ✅ Test  → original images only")
print("  ✅ Valid → original images only")
print("  ✅ Train → originals + 18 augmented versions each")

