import tensorflow as tf
import numpy as np
import mlflow
import os
import matplotlib.pyplot as plt
from tensorflow.keras import layers, models
from tensorflow.keras.callbacks import EarlyStopping, ReduceLROnPlateau
from sklearn.utils.class_weight import compute_class_weight
from sklearn.metrics import confusion_matrix, classification_report

# ── SETTINGS ──────────────────────────────────────────────────────────────────
CLEAN_DATASET = "/content/clean_dataset"
IMG_SIZE      = (224, 224)
BATCH_SIZE    = 32

mlflow.set_experiment("Capacitor_Polarity_Detection")

# ── LOAD DATA ─────────────────────────────────────────────────────────────────
train_ds = tf.keras.preprocessing.image_dataset_from_directory(
    f"{CLEAN_DATASET}/train",
    image_size=IMG_SIZE, batch_size=BATCH_SIZE, shuffle=True)

valid_ds = tf.keras.preprocessing.image_dataset_from_directory(
    f"{CLEAN_DATASET}/valid",
    image_size=IMG_SIZE, batch_size=BATCH_SIZE, shuffle=False)

test_ds = tf.keras.preprocessing.image_dataset_from_directory(
    f"{CLEAN_DATASET}/test",
    image_size=IMG_SIZE, batch_size=BATCH_SIZE, shuffle=False)

class_names = train_ds.class_names
print("Classes:", class_names)

# ── CLASS WEIGHTS ─────────────────────────────────────────────────────────────
all_labels = []
for _, y in train_ds:
    all_labels.extend(y.numpy())
all_labels = np.array(all_labels)

class_weights = compute_class_weight(
    class_weight="balanced",
    classes=np.unique(all_labels),
    y=all_labels
)
class_weights = dict(enumerate(class_weights))
print("Class weights:", class_weights)

# ── BUILD CNN V1 ──────────────────────────────────────────────────────────────
def build_cnn_v1():
    return models.Sequential([
        layers.Rescaling(1./255, input_shape=(224, 224, 3)),
        layers.Conv2D(32,  (3,3), activation='relu'),
        layers.MaxPooling2D(),
        layers.Conv2D(64,  (3,3), activation='relu'),
        layers.MaxPooling2D(),
        layers.Conv2D(128, (3,3), activation='relu'),
        layers.MaxPooling2D(),
        layers.GlobalAveragePooling2D(),
        layers.Dense(64, activation='relu'),
        layers.Dense(4,  activation='softmax')
    ], name="CNN_V1")

# ── TRAIN WITH MLFLOW ─────────────────────────────────────────────────────────
with mlflow.start_run(run_name="CNN_V1_DataV3_Clean"):

    model = build_cnn_v1()

    model.compile(
        optimizer='adam',
        loss='sparse_categorical_crossentropy',
        metrics=['accuracy']
    )

    model.summary()

    # Log parameters
    mlflow.log_param("model_name",        "CNN_V1")
    mlflow.log_param("data_version",      "V3_Clean")
    mlflow.log_param("data_description",  "193 originals split first then augmented — no leakage")
    mlflow.log_param("train_images",      2641)
    mlflow.log_param("valid_images",      27)
    mlflow.log_param("test_images",       27)
    mlflow.log_param("batch_size",        BATCH_SIZE)
    mlflow.log_param("optimizer",         "Adam")
    mlflow.log_param("learning_rate",     "0.001")
    mlflow.log_param("image_size",        "224x224")
    mlflow.log_param("num_classes",       4)
    mlflow.log_param("class_weights",     "balanced")
    mlflow.log_param("train_Bottom",      570)
    mlflow.log_param("train_Left",        817)
    mlflow.log_param("train_Right",       513)
    mlflow.log_param("train_Top",         741)

    callbacks = [
        EarlyStopping(
            monitor='val_accuracy',
            patience=5,
            restore_best_weights=True,
            verbose=1
        ),
        ReduceLROnPlateau(
            monitor='val_loss',
            factor=0.5,
            patience=3,
            verbose=1
        )
    ]

    # Train
    history = model.fit(
        train_ds,
        validation_data=valid_ds,
        epochs=20,
        class_weight=class_weights,
        callbacks=callbacks
    )

    # Log per epoch metrics
    for ep, (a, v) in enumerate(zip(
        history.history['accuracy'],
        history.history['val_accuracy']
    )):
        mlflow.log_metric("train_accuracy", a, step=ep)
        mlflow.log_metric("val_accuracy",   v, step=ep)

    for ep, (a, v) in enumerate(zip(
        history.history['loss'],
        history.history['val_loss']
    )):
        mlflow.log_metric("train_loss", a, step=ep)
        mlflow.log_metric("val_loss",   v, step=ep)

    # Evaluate on test
    test_loss, test_acc = model.evaluate(test_ds, verbose=0)
    print(f"\nTest Accuracy : {test_acc:.2%}")
    print(f"Test Loss     : {test_loss:.4f}")

    # Confusion matrix + classification report
    y_true, y_pred = [], []
    for images, lbls in test_ds:
        preds = model.predict(images, verbose=0)
        y_true.extend(lbls.numpy())
        y_pred.extend(np.argmax(preds, axis=1))

    cm     = confusion_matrix(y_true, y_pred)
    report = classification_report(
        y_true, y_pred,
        target_names=class_names,
        output_dict=True
    )

    print("\nConfusion Matrix:")
    print(cm)
    print("\nClassification Report:")
    print(classification_report(y_true, y_pred, target_names=class_names))

    # Log test metrics
    mlflow.log_metric("test_accuracy", test_acc)
    mlflow.log_metric("test_loss",     test_loss)
    for cls in class_names:
        mlflow.log_metric(f"{cls}_precision", report[cls]['precision'])
        mlflow.log_metric(f"{cls}_recall",    report[cls]['recall'])
        mlflow.log_metric(f"{cls}_f1",        report[cls]['f1-score'])
    mlflow.log_metric("macro_f1", report['macro avg']['f1-score'])

    # Save confusion matrix plot
    fig, ax = plt.subplots(figsize=(6, 5))
    im = ax.imshow(cm, cmap='Blues')
    ax.set_xticks(range(len(class_names)))
    ax.set_yticks(range(len(class_names)))
    ax.set_xticklabels(class_names, rotation=45)
    ax.set_yticklabels(class_names)
    for i in range(len(class_names)):
        for j in range(len(class_names)):
            ax.text(j, i, cm[i,j], ha='center', va='center')
    ax.set_xlabel('Predicted')
    ax.set_ylabel('Actual')
    ax.set_title('CNN V1 — Confusion Matrix')
    plt.tight_layout()
    plt.savefig("/tmp/cnn_v1_cm.png")
    plt.show()
    mlflow.log_artifact("/tmp/cnn_v1_cm.png", "plots")

    # Save training history plot
    fig, axes = plt.subplots(1, 2, figsize=(12, 4))
    axes[0].plot(history.history['accuracy'],     label='Train')
    axes[0].plot(history.history['val_accuracy'], label='Val')
    axes[0].set_title('CNN V1 — Accuracy')
    axes[0].legend()
    axes[1].plot(history.history['loss'],         label='Train')
    axes[1].plot(history.history['val_loss'],     label='Val')
    axes[1].set_title('CNN V1 — Loss')
    axes[1].legend()
    plt.tight_layout()
    plt.savefig("/tmp/cnn_v1_history.png")
    plt.show()
    mlflow.log_artifact("/tmp/cnn_v1_history.png", "plots")

    # Save model
    model.save("/content/drive/MyDrive/CNN_V1_Clean.keras")
    mlflow.log_artifact("/content/drive/MyDrive/CNN_V1_Clean.keras", "models")

    print(f"\n✅ CNN V1 logged to MLflow!")
    print(f"   Test Accuracy : {test_acc:.2%}")
    print(f"   Macro F1      : {report['macro avg']['f1-score']:.2%}")

from tensorflow.keras import layers, models
from tensorflow.keras.callbacks import EarlyStopping, ReduceLROnPlateau
import mlflow

def build_cnn_v2():
    return models.Sequential([
        layers.Rescaling(1./255, input_shape=(224, 224, 3)),
        layers.Conv2D(32,  (3,3), activation='relu'),
        layers.BatchNormalization(),
        layers.MaxPooling2D(),
        layers.Conv2D(64,  (3,3), activation='relu'),
        layers.BatchNormalization(),
        layers.MaxPooling2D(),
        layers.Conv2D(128, (3,3), activation='relu'),
        layers.BatchNormalization(),
        layers.MaxPooling2D(),
        layers.GlobalAveragePooling2D(),
        layers.Dense(64, activation='relu'),
        layers.Dense(4,  activation='softmax')
    ], name="CNN_V2")

with mlflow.start_run(run_name="CNN_V2_DataV3_Clean"):

    model_v2 = build_cnn_v2()
    model_v2.compile(
        optimizer='adam',
        loss='sparse_categorical_crossentropy',
        metrics=['accuracy']
    )

    mlflow.log_param("model_name",       "CNN_V2")
    mlflow.log_param("data_version",     "V3_Clean")
    mlflow.log_param("improvement_over", "CNN_V1: added BatchNormalization")
    mlflow.log_param("train_images",     2641)
    mlflow.log_param("valid_images",     27)
    mlflow.log_param("test_images",      27)
    mlflow.log_param("batch_size",       32)
    mlflow.log_param("optimizer",        "Adam")
    mlflow.log_param("image_size",       "224x224")
    mlflow.log_param("num_classes",      4)
    mlflow.log_param("class_weights",    "balanced")

    callbacks = [
        EarlyStopping(monitor='val_accuracy', patience=5,
                      restore_best_weights=True, verbose=1),
        ReduceLROnPlateau(monitor='val_loss', factor=0.5,
                          patience=3, verbose=1)
    ]

    history_v2 = model_v2.fit(
        train_ds,
        validation_data=valid_ds,
        epochs=20,
        class_weight=class_weights,
        callbacks=callbacks
    )

    # Log per epoch
    for ep, (a, v) in enumerate(zip(
        history_v2.history['accuracy'],
        history_v2.history['val_accuracy']
    )):
        mlflow.log_metric("train_accuracy", a, step=ep)
        mlflow.log_metric("val_accuracy",   v, step=ep)

    # Evaluate
    test_loss, test_acc = model_v2.evaluate(test_ds, verbose=0)

    y_true, y_pred = [], []
    for images, lbls in test_ds:
        preds = model_v2.predict(images, verbose=0)
        y_true.extend(lbls.numpy())
        y_pred.extend(np.argmax(preds, axis=1))

    cm     = confusion_matrix(y_true, y_pred)
    report = classification_report(
        y_true, y_pred, target_names=class_names, output_dict=True)

    print(f"\nTest Accuracy : {test_acc:.2%}")
    print(f"Test Loss     : {test_loss:.4f}")
    print("\nConfusion Matrix:")
    print(cm)
    print("\nClassification Report:")
    print(classification_report(y_true, y_pred, target_names=class_names))

    # Log metrics
    mlflow.log_metric("test_accuracy", test_acc)
    mlflow.log_metric("test_loss",     test_loss)
    mlflow.log_metric("macro_f1", report['macro avg']['f1-score'])
    for cls in class_names:
        mlflow.log_metric(f"{cls}_f1", report[cls]['f1-score'])

    # Confusion matrix plot
    fig, ax = plt.subplots(figsize=(6,5))
    ax.imshow(cm, cmap='Blues')
    ax.set_xticks(range(len(class_names)))
    ax.set_yticks(range(len(class_names)))
    ax.set_xticklabels(class_names, rotation=45)
    ax.set_yticklabels(class_names)
    for i in range(len(class_names)):
        for j in range(len(class_names)):
            ax.text(j, i, cm[i,j], ha='center', va='center')
    ax.set_title('CNN V2 — Confusion Matrix')
    plt.tight_layout()
    plt.savefig("/tmp/cnn_v2_cm.png")
    plt.show()
    mlflow.log_artifact("/tmp/cnn_v2_cm.png", "plots")

    # History plot
    fig, axes = plt.subplots(1, 2, figsize=(12,4))
    axes[0].plot(history_v2.history['accuracy'],     label='Train')
    axes[0].plot(history_v2.history['val_accuracy'], label='Val')
    axes[0].set_title('CNN V2 — Accuracy')
    axes[0].legend()
    axes[1].plot(history_v2.history['loss'],         label='Train')
    axes[1].plot(history_v2.history['val_loss'],     label='Val')
    axes[1].set_title('CNN V2 — Loss')
    axes[1].legend()
    plt.tight_layout()
    plt.savefig("/tmp/cnn_v2_history.png")
    plt.show()
    mlflow.log_artifact("/tmp/cnn_v2_history.png", "plots")

    model_v2.save("/content/drive/MyDrive/CNN_V2_Clean.keras")
    mlflow.log_artifact(
        "/content/drive/MyDrive/CNN_V2_Clean.keras", "models")

    print(f"\n✅ CNN V2 logged to MLflow!")
    print(f"   Test Accuracy : {test_acc:.2%}")
    print(f"   Macro F1      : {report['macro avg']['f1-score']:.2%}")

# After training
