# ═══════════════════════════════════════════════════════════
# STEP 2 — Merge ALL images, then re-split properly
# ═══════════════════════════════════════════════════════════
import os, shutil, random

random.seed(42)

RAW_PATH    = dataset.location
SPLIT_PATH  = "/content/split_dataset"

# Merge all splits into one pool per class
print("Merging all images into one pool...")
for cls in ["Bottom", "Left", "Right", "Top"]:
    pool_dir = f"/content/pool/{cls}"
    os.makedirs(pool_dir, exist_ok=True)

    for split in ["train", "valid", "test"]:
        src = f"{RAW_PATH}/{split}/{cls}"
        if not os.path.exists(src):
            continue
        for f in os.listdir(src):
            src_file = os.path.join(src, f)
            # Rename to avoid duplicates
            dst_file = os.path.join(pool_dir, f"{split}_{f}")
            shutil.copy2(src_file, dst_file)

    count = len(os.listdir(pool_dir))
    print(f"  {cls}: {count} images in pool")

# Re-split 70% train / 15% valid / 15% test
print("\nSplitting 70/15/15...")
for cls in ["Bottom", "Left", "Right", "Top"]:
    pool_dir  = f"/content/pool/{cls}"
    all_files = os.listdir(pool_dir)
    random.shuffle(all_files)

    n       = len(all_files)
    n_train = int(n * 0.70)
    n_valid = int(n * 0.15)

    splits = {
        "train": all_files[:n_train],
        "valid": all_files[n_train:n_train + n_valid],
        "test":  all_files[n_train + n_valid:]
    }

    for split, files in splits.items():
        dst = f"{SPLIT_PATH}/{split}/{cls}"
        os.makedirs(dst, exist_ok=True)
        for f in files:
            shutil.copy2(os.path.join(pool_dir, f),
                         os.path.join(dst, f))

# Summary
print("\n✅ Clean split done:")
for split in ["train", "valid", "test"]:
    print(f"\n{split.upper()}")
    total = 0
    for cls in ["Bottom", "Left", "Right", "Top"]:
        path  = f"{SPLIT_PATH}/{split}/{cls}"
        count = len(os.listdir(path))
        total += count
        print(f"  {cls}: {count}")
    print(f"  Total: {total}")

# ═══════════════════════════════════════════════════════════
# STEP 3 — Augment ONLY the train set
# ═══════════════════════════════════════════════════════════
import numpy as np
from PIL import Image, ImageEnhance, ImageOps
import cv2, os, shutil

SPLIT_PATH = "/content/split_dataset"
AUG_PATH   = "/content/final_dataset"

# ── Augmentation functions ─────────────────────────────────
def aug_hue_shift(img, shift):
    arr = np.array(img.convert("RGB")).astype(np.uint8)
    hsv = cv2.cvtColor(arr, cv2.COLOR_RGB2HSV).astype(np.int32)
    hsv[:,:,0] = (hsv[:,:,0] + shift) % 180
    return Image.fromarray(cv2.cvtColor(
        np.clip(hsv,0,255).astype(np.uint8), cv2.COLOR_HSV2RGB))

def aug_brightness(img, f):
    return ImageEnhance.Brightness(img).enhance(f)

def aug_contrast(img, f):
    return ImageEnhance.Contrast(img).enhance(f)

def aug_saturation(img, f):
    return ImageEnhance.Color(img).enhance(f)

def aug_grayscale(img):
    return ImageOps.grayscale(img).convert("RGB")

def aug_channel(img, ch, f):
    arr = np.array(img).astype(np.float32)
    arr[:,:,ch] = np.clip(arr[:,:,ch]*f, 0, 255)
    return Image.fromarray(arr.astype(np.uint8))

def get_variants(img):
    return {
        "hue_p30":    aug_hue_shift(img,  30),
        "hue_n30":    aug_hue_shift(img, -30),
        "hue_p60":    aug_hue_shift(img,  60),
        "bright_up":  aug_brightness(img, 1.4),
        "bright_dn":  aug_brightness(img, 0.6),
        "contrast_hi":aug_contrast(img, 1.5),
        "contrast_lo":aug_contrast(img, 0.5),
        "sat_hi":     aug_saturation(img, 1.8),
        "sat_lo":     aug_saturation(img, 0.3),
        "grayscale":  aug_grayscale(img),
        "red_cast":   aug_channel(img, 0, 1.5),
        "blue_cast":  aug_channel(img, 2, 1.5),
    }

total_saved = 0

for split in ["train", "valid", "test"]:
    for cls in ["Bottom", "Left", "Right", "Top"]:

        src = f"{SPLIT_PATH}/{split}/{cls}"
        dst = f"{AUG_PATH}/{split}/{cls}"
        os.makedirs(dst, exist_ok=True)

        if not os.path.exists(src):
            continue

        images = [f for f in os.listdir(src)
                  if f.lower().endswith(('.jpg','.jpeg','.png'))]

        for fname in images:
            img  = Image.open(os.path.join(src, fname)).convert("RGB")
            stem = os.path.splitext(fname)[0]

            # Always copy original
            img.save(os.path.join(dst, fname), quality=95)
            total_saved += 1

            # Augment ONLY train
            if split == "train":
                for label, aug_img in get_variants(img).items():
                    aug_img.save(
                        os.path.join(dst, f"{stem}_{label}.jpg"),
                        quality=95
                    )
                    total_saved += 1

# Summary
print(f"\n✅ Final dataset ready! Total images: {total_saved}")
for split in ["train", "valid", "test"]:
    print(f"\n{split.upper()}")
    total = 0
    for cls in ["Bottom", "Left", "Right", "Top"]:
        path  = f"{AUG_PATH}/{split}/{cls}"
        count = len(os.listdir(path)) if os.path.exists(path) else 0
        total += count
        print(f"  {cls}: {count}")
    print(f"  Total: {total}")

# ═══════════════════════════════════════════════════════════
# STEP 4 — Load final dataset and verify
# ═══════════════════════════════════════════════════════════
import tensorflow as tf

