# REBUILD with 80/10/10 split — proper for small dataset
# ═══════════════════════════════════════════════════════════
import os, shutil, random
import numpy as np
from PIL import Image, ImageEnhance, ImageOps
import cv2

random.seed(42)

# Clean old data
for path in ["/content/split_dataset", "/content/final_dataset", "/content/pool"]:
    if os.path.exists(path):
        shutil.rmtree(path)
        print(f"🗑️ Cleaned {path}")

RAW_PATH   = dataset.location
SPLIT_PATH = "/content/split_dataset"
AUG_PATH   = "/content/final_dataset"

# ── STEP 1: Merge all into pool per class ──────────────────
print("\nMerging into pool...")
for cls in ["Bottom", "Left", "Right", "Top"]:
    pool_dir = f"/content/pool/{cls}"
    os.makedirs(pool_dir, exist_ok=True)
    for split in ["train", "valid", "test"]:
        src = f"{RAW_PATH}/{split}/{cls}"
        if not os.path.exists(src):
            continue
        for f in os.listdir(src):
            shutil.copy2(
                os.path.join(src, f),
                os.path.join(pool_dir, f"{split}_{f}")
            )
    print(f"  {cls}: {len(os.listdir(pool_dir))} raw images")

# ── STEP 2: Split 80/10/10 per class ──────────────────────
print("\nSplitting 80/10/10 per class...")
split_summary = {}
for cls in ["Bottom", "Left", "Right", "Top"]:
    pool_dir  = f"/content/pool/{cls}"
    all_files = sorted(os.listdir(pool_dir))
    random.shuffle(all_files)

    n       = len(all_files)
    n_valid = max(4, int(n * 0.10))  # at least 4 per class
    n_test  = max(4, int(n * 0.10))  # at least 4 per class
    n_train = n - n_valid - n_test

    splits = {
        "train": all_files[:n_train],
        "valid": all_files[n_train:n_train + n_valid],
        "test":  all_files[n_train + n_valid:]
    }

    split_summary[cls] = {k: len(v) for k, v in splits.items()}

    for split, files in splits.items():
        dst = f"{SPLIT_PATH}/{split}/{cls}"
        os.makedirs(dst, exist_ok=True)
        for f in files:
            shutil.copy2(os.path.join(pool_dir, f),
                         os.path.join(dst, f))

print("\nRaw split counts:")
for cls, counts in split_summary.items():
    print(f"  {cls}: train={counts['train']} valid={counts['valid']} test={counts['test']}")

# ── STEP 3: 18-variant augmentation ONLY on train ─────────
print("\nAugmenting train set (18 variants)...")

def aug_hue_shift(img, shift_deg):
    arr = np.array(img.convert("RGB")).astype(np.uint8)
    hsv = cv2.cvtColor(arr, cv2.COLOR_RGB2HSV).astype(np.int32)
    hsv[:,:,0] = (hsv[:,:,0] + shift_deg) % 180
    return Image.fromarray(cv2.cvtColor(
        np.clip(hsv,0,255).astype(np.uint8), cv2.COLOR_HSV2RGB))

def get_all_variants(img):
    def bright(f): return ImageEnhance.Brightness(img).enhance(f)
    def contrast(f): return ImageEnhance.Contrast(img).enhance(f)
    def sat(f): return ImageEnhance.Color(img).enhance(f)
    def channel(ch, f):
        arr = np.array(img).astype(np.float32)
        arr[:,:,ch] = np.clip(arr[:,:,ch]*f, 0, 255)
        return Image.fromarray(arr.astype(np.uint8))
    def warm():
        arr = np.array(img).astype(np.float32)
        arr[:,:,0] = np.clip(arr[:,:,0]*1.3, 0, 255)
        arr[:,:,2] = np.clip(arr[:,:,2]*0.7, 0, 255)
        return Image.fromarray(arr.astype(np.uint8))
    def cool():
        arr = np.array(img).astype(np.float32)
        arr[:,:,0] = np.clip(arr[:,:,0]*0.7, 0, 255)
        arr[:,:,2] = np.clip(arr[:,:,2]*1.3, 0, 255)
        return Image.fromarray(arr.astype(np.uint8))

    return {
        "Hue_p30":       aug_hue_shift(img,  30),
        "Hue_p60":       aug_hue_shift(img,  60),
        "Hue_p90":       aug_hue_shift(img,  90),
        "Hue_p120":      aug_hue_shift(img, 120),
        "Hue_n30":       aug_hue_shift(img, -30),
        "Hue_n60":       aug_hue_shift(img, -60),
        "Sat_High":      sat(1.8),
        "Sat_Low":       sat(0.3),
        "Grayscale":     ImageOps.grayscale(img).convert("RGB"),
        "Red_Cast":      channel(0, 1.6),
        "Green_Cast":    channel(1, 1.6),
        "Blue_Cast":     channel(2, 1.6),
        "Warm_Tone":     warm(),
        "Cool_Tone":     cool(),
        "Bright":        bright(1.4),
        "Dark":          bright(0.6),
        "Contrast_High": contrast(1.5),
        "Contrast_Low":  contrast(0.5),
    }

total_saved = 0
for split in ["train", "valid", "test"]:
    for cls in ["Bottom", "Left", "Right", "Top"]:
        src = f"{SPLIT_PATH}/{split}/{cls}"
        dst = f"{AUG_PATH}/{split}/{cls}"
        os.makedirs(dst, exist_ok=True)

        if not os.path.exists(src):
            continue

        for fname in os.listdir(src):
            if not fname.lower().endswith(('.jpg','.jpeg','.png')):
                continue
            img  = Image.open(os.path.join(src, fname)).convert("RGB")
            stem = os.path.splitext(fname)[0]

            img.save(os.path.join(dst, fname), quality=95)
            total_saved += 1

            if split == "train":
                for label, aug_img in get_all_variants(img).items():
                    aug_img.save(
                        os.path.join(dst, f"{stem}_{label}.jpg"),
                        quality=95
                    )
                    total_saved += 1

# ── STEP 4: Final summary ──────────────────────────────────
print(f"\n✅ Total images saved: {total_saved}")
print("\nFinal counts:")
for split in ["train", "valid", "test"]:
    print(f"\n{split.upper()}")
    total = 0
    for cls in ["Bottom", "Left", "Right", "Top"]:
        path  = f"{AUG_PATH}/{split}/{cls}"
        count = len(os.listdir(path)) if os.path.exists(path) else 0
        total += count
        print(f"  {cls}: {count}")
    print(f"  Total: {total}")

print("\nNo leakage confirmation:")
print("  ✅ Test  → original images only")
print("  ✅ Valid → original images only")
print("  ✅ Train → originals + 18 augmented versions each")

# ═══════════════════════════════════════════════════════════
# CNN V3 TRAINING
# ═══════════════════════════════════════════════════════════
import numpy as np, mlflow, mlflow.keras, os
import matplotlib.pyplot as plt
import seaborn as sns
import tensorflow as tf
from tensorflow.keras import layers, models, regularizers
from tensorflow.keras.callbacks import EarlyStopping, ReduceLROnPlateau
from sklearn.metrics import confusion_matrix, classification_report
from sklearn.utils.class_weight import compute_class_weight

# ── Class weights ──────────────────────────────────────────
labels = []
for _, y in train_ds:
    labels.extend(y.numpy())
labels = np.array(labels)
cw = compute_class_weight("balanced", classes=np.unique(labels), y=labels)
class_weights = dict(enumerate(cw))
print("Class weights:", class_weights)

# ── Build CNN V3 ───────────────────────────────────────────
reg = regularizers.l2(1e-4)

model_v3 = models.Sequential([

    layers.Rescaling(1./255, input_shape=(224, 224, 3)),

    # Block 1
    layers.Conv2D(32, (3,3), activation='relu',
                  padding='same', kernel_regularizer=reg),
    layers.BatchNormalization(),
    layers.Conv2D(32, (3,3), activation='relu',
                  padding='same', kernel_regularizer=reg),
    layers.MaxPooling2D(),
    layers.Dropout(0.25),

    # Block 2
    layers.Conv2D(64, (3,3), activation='relu',
                  padding='same', kernel_regularizer=reg),
    layers.BatchNormalization(),
    layers.Conv2D(64, (3,3), activation='relu',
                  padding='same', kernel_regularizer=reg),
    layers.MaxPooling2D(),
    layers.Dropout(0.25),

    # Block 3
    layers.Conv2D(128, (3,3), activation='relu',
                  padding='same', kernel_regularizer=reg),
    layers.BatchNormalization(),
    layers.Conv2D(128, (3,3), activation='relu',
                  padding='same', kernel_regularizer=reg),
    layers.MaxPooling2D(),
    layers.Dropout(0.3),

    layers.GlobalAveragePooling2D(),
    layers.Dense(128, activation='relu', kernel_regularizer=reg),
    layers.BatchNormalization(),
    layers.Dropout(0.5),
    layers.Dense(4, activation='softmax')
])

model_v3.compile(
    optimizer=tf.keras.optimizers.Adam(1e-3),
    loss='sparse_categorical_crossentropy',
    metrics=['accuracy']
)
model_v3.summary()

# ── Callbacks ──────────────────────────────────────────────
callbacks = [
    EarlyStopping(
        monitor='val_accuracy',
        patience=10,
        restore_best_weights=True,
        verbose=1
    ),
    ReduceLROnPlateau(
        monitor='val_loss',
        factor=0.5,
        patience=4,
        min_lr=1e-6,
        verbose=1
    )
]

# ── Train ──────────────────────────────────────────────────
print("\n🚀 Training CNN V3 on GPU...")
history_v3 = model_v3.fit(
    train_ds,
    validation_data=valid_ds,
    epochs=50,
    class_weight=class_weights,
    callbacks=callbacks
)

# ── Evaluate ───────────────────────────────────────────────
test_loss, test_acc = model_v3.evaluate(test_ds, verbose=0)

y_true, y_pred = [], []
for images, lbls in test_ds:
    preds = model_v3.predict(images, verbose=0)
    y_true.extend(lbls.numpy())
    y_pred.extend(np.argmax(preds, axis=1))

report   = classification_report(y_true, y_pred,
               target_names=class_names, output_dict=True)
cm       = confusion_matrix(y_true, y_pred)
macro_f1 = report['macro avg']['f1-score']

print(f"\nTest Accuracy : {test_acc:.2%}")
print(f"Test Loss     : {test_loss:.4f}")
print(f"Macro F1      : {macro_f1:.2%}")
print(classification_report(y_true, y_pred, target_names=class_names))

# ── Plots ──────────────────────────────────────────────────
fig, axes = plt.subplots(1, 3, figsize=(18, 5))
fig.suptitle(f'CNN V3 — Acc:{test_acc:.2%}  F1:{macro_f1:.2%}',
             fontsize=14, fontweight='bold')

axes[0].plot(history_v3.history['accuracy'],     label='Train')
axes[0].plot(history_v3.history['val_accuracy'], label='Val')
axes[0].set_title('Accuracy')
axes[0].set_xlabel('Epoch')
axes[0].legend()

axes[1].plot(history_v3.history['loss'],     label='Train')
axes[1].plot(history_v3.history['val_loss'], label='Val')
axes[1].set_title('Loss')
axes[1].set_xlabel('Epoch')
axes[1].legend()

sns.heatmap(cm, annot=True, fmt='d', cmap='Blues',
            xticklabels=class_names,
            yticklabels=class_names, ax=axes[2])
axes[2].set_title('Confusion Matrix')
axes[2].set_ylabel('True')
axes[2].set_xlabel('Predicted')

plt.tight_layout()
plot_path = '/content/cnn_v3_results.png'
plt.savefig(plot_path, bbox_inches='tight', dpi=150)
plt.show()

# ── Save ───────────────────────────────────────────────────
model_v3.save('/content/drive/MyDrive/CNN_V3_Clean.keras')
print("✅ Model saved to Drive!")

# ── MLflow ─────────────────────────────────────────────────
mlflow.set_tracking_uri("sqlite:////content/mlflow.db")
mlflow.set_experiment("Capacitor_Orientation")

with mlflow.start_run(run_name="CNN_V3_Aug18_80split"):

    mlflow.log_param("model",         "CNN_V3")
    mlflow.log_param("img_size",      "224x224")
    mlflow.log_param("batch_size",    16)
    mlflow.log_param("epochs_run",    len(history_v3.history['accuracy']))
    mlflow.log_param("optimizer",     "Adam_1e-3")
    mlflow.log_param("dropout",       "0.25/0.25/0.3/0.5")
    mlflow.log_param("l2_reg",        "1e-4")
    mlflow.log_param("batch_norm",    "True")
    mlflow.log_param("class_weights", "True")
    mlflow.log_param("train_images",  2945)
    mlflow.log_param("valid_images",  19)
    mlflow.log_param("test_images",   19)
    mlflow.log_param("aug_variants",  18)
    mlflow.log_param("split",         "80_10_10")
    mlflow.log_param("architecture",  "3xDoubleConvBlock+GAP+Dense128")

    mlflow.log_metric("test_accuracy", test_acc)
    mlflow.log_metric("test_loss",     test_loss)
    mlflow.log_metric("macro_f1",      macro_f1)

    for cls in class_names:
        mlflow.log_metric(f"{cls}_f1",        report[cls]['f1-score'])
        mlflow.log_metric(f"{cls}_precision", report[cls]['precision'])
        mlflow.log_metric(f"{cls}_recall",    report[cls]['recall'])

    mlflow.log_artifact(plot_path)
    mlflow.keras.log_model(model_v3, "cnn_v3_model")

    print(f"\n✅ CNN V3 logged to MLflow!")
    print(f"   Test Accuracy : {test_acc:.2%}")
    print(f"   Macro F1      : {macro_f1:.2%}")

# ═══════════════════════════════════════════════════════════
# CLEAN REBUILD — Fix filename conflicts
# ═══════════════════════════════════════════════════════════
import os, shutil, random
import numpy as np
from PIL import Image, ImageEnhance, ImageOps
import cv2

random.seed(42)

# Clean everything
for path in ["/content/split_dataset", "/content/final_dataset", "/content/pool"]:
    if os.path.exists(path):
        shutil.rmtree(path)
        print(f"🗑️ Cleaned {path}")

RAW_PATH   = dataset.location
SPLIT_PATH = "/content/split_dataset"
AUG_PATH   = "/content/final_dataset"

# ── STEP 1: Merge pool with NUMBERED names (no prefix conflicts) ──
print("\nMerging into pool...")
for cls in ["Bottom", "Left", "Right", "Top"]:
    pool_dir = f"/content/pool/{cls}"
    os.makedirs(pool_dir, exist_ok=True)
    counter = 0
    for split in ["train", "valid", "test"]:
        src = f"{RAW_PATH}/{split}/{cls}"
        if not os.path.exists(src):
            continue
        for f in os.listdir(src):
            if not f.lower().endswith(('.jpg','.jpeg','.png')):
                continue
            ext = os.path.splitext(f)[1]
            # Use numbered names to avoid ANY conflicts
            dst_name = f"{cls}_{counter:04d}{ext}"
            shutil.copy2(
                os.path.join(src, f),
                os.path.join(pool_dir, dst_name)
            )
            counter += 1
    print(f"  {cls}: {counter} raw images")

# ── STEP 2: Split 80/10/10 ────────────────────────────────
print("\nSplitting 80/10/10...")
for cls in ["Bottom", "Left", "Right", "Top"]:
    pool_dir  = f"/content/pool/{cls}"
    all_files = sorted(os.listdir(pool_dir))
    random.shuffle(all_files)

    n       = len(all_files)
    n_valid = max(4, int(n * 0.10))
    n_test  = max(4, int(n * 0.10))
    n_train = n - n_valid - n_test

    splits = {
        "train": all_files[:n_train],
        "valid": all_files[n_train:n_train + n_valid],
        "test":  all_files[n_train + n_valid:]
    }

    for split, files in splits.items():
        dst = f"{SPLIT_PATH}/{split}/{cls}"
        os.makedirs(dst, exist_ok=True)
        for f in files:
            shutil.copy2(
                os.path.join(pool_dir, f),
                os.path.join(dst, f)
            )

    print(f"  {cls}: train={n_train} valid={n_valid} test={n_test}")

# ── STEP 3: Augment ONLY train ────────────────────────────
print("\nAugmenting train set (18 variants)...")

def aug_hue_shift(img, shift_deg):
    arr = np.array(img.convert("RGB")).astype(np.uint8)
    hsv = cv2.cvtColor(arr, cv2.COLOR_RGB2HSV).astype(np.int32)
    hsv[:,:,0] = (hsv[:,:,0] + shift_deg) % 180
    return Image.fromarray(cv2.cvtColor(
        np.clip(hsv,0,255).astype(np.uint8), cv2.COLOR_HSV2RGB))

def get_all_variants(img):
    def bright(f):   return ImageEnhance.Brightness(img).enhance(f)
    def contrast(f): return ImageEnhance.Contrast(img).enhance(f)
    def sat(f):      return ImageEnhance.Color(img).enhance(f)
    def channel(ch, f):
        arr = np.array(img).astype(np.float32)
        arr[:,:,ch] = np.clip(arr[:,:,ch]*f, 0, 255)
        return Image.fromarray(arr.astype(np.uint8))
    def warm():
        arr = np.array(img).astype(np.float32)
        arr[:,:,0] = np.clip(arr[:,:,0]*1.3, 0, 255)
        arr[:,:,2] = np.clip(arr[:,:,2]*0.7, 0, 255)
        return Image.fromarray(arr.astype(np.uint8))
    def cool():
        arr = np.array(img).astype(np.float32)
        arr[:,:,0] = np.clip(arr[:,:,0]*0.7, 0, 255)
        arr[:,:,2] = np.clip(arr[:,:,2]*1.3, 0, 255)
        return Image.fromarray(arr.astype(np.uint8))

    return {
        "hue_p30":   aug_hue_shift(img,  30),
        "hue_p60":   aug_hue_shift(img,  60),
        "hue_p90":   aug_hue_shift(img,  90),
        "hue_p120":  aug_hue_shift(img, 120),
        "hue_n30":   aug_hue_shift(img, -30),
        "hue_n60":   aug_hue_shift(img, -60),
        "sat_hi":    sat(1.8),
        "sat_lo":    sat(0.3),
        "gray":      ImageOps.grayscale(img).convert("RGB"),
        "red":       channel(0, 1.6),
        "green":     channel(1, 1.6),
        "blue":      channel(2, 1.6),
        "warm":      warm(),
        "cool":      cool(),
        "bright":    bright(1.4),
        "dark":      bright(0.6),
        "cont_hi":   contrast(1.5),
        "cont_lo":   contrast(0.5),
    }

total_saved = 0
for split in ["train", "valid", "test"]:
    for cls in ["Bottom", "Left", "Right", "Top"]:
        src = f"{SPLIT_PATH}/{split}/{cls}"
        dst = f"{AUG_PATH}/{split}/{cls}"
        os.makedirs(dst, exist_ok=True)

        if not os.path.exists(src):
            continue

        for fname in os.listdir(src):
            if not fname.lower().endswith(('.jpg','.jpeg','.png')):
                continue

            img  = Image.open(os.path.join(src, fname)).convert("RGB")
            stem = os.path.splitext(fname)[0]

            # Save original
            img.save(os.path.join(dst, fname), quality=95)
            total_saved += 1

            # Augment ONLY train
            if split == "train":
                for label, aug_img in get_all_variants(img).items():
                    save_name = f"{stem}_{label}.jpg"
                    aug_img.save(
                        os.path.join(dst, save_name),
                        quality=95
                    )
                    total_saved += 1

# ── Summary ────────────────────────────────────────────────
print(f"\n✅ Total images: {total_saved}")
for split in ["train", "valid", "test"]:
    print(f"\n{split.upper()}")
    total = 0
    for cls in ["Bottom", "Left", "Right", "Top"]:
        path  = f"{AUG_PATH}/{split}/{cls}"
        count = len(os.listdir(path)) if os.path.exists(path) else 0
        total += count
        print(f"  {cls}: {count}")
    print(f"  Total: {total}")

print("\n✅ No leakage:")
print("  Test  → original images only")
print("  Valid → original images only")
print("  Train → originals + 18 augmented versions each")

# ── Load Dataset ───────────────────────────────────────────
import tensorflow as tf, os

DATASET_PATH = "/content/final_dataset"
IMG_SIZE     = (224, 224)
BATCH_SIZE   = 16
AUTOTUNE     = tf.data.AUTOTUNE

train_raw = tf.keras.preprocessing.image_dataset_from_directory(
    f"{DATASET_PATH}/train",
    image_size=IMG_SIZE, batch_size=BATCH_SIZE, shuffle=True
)
valid_raw = tf.keras.preprocessing.image_dataset_from_directory(
    f"{DATASET_PATH}/valid",
    image_size=IMG_SIZE, batch_size=BATCH_SIZE, shuffle=False
)
test_raw = tf.keras.preprocessing.image_dataset_from_directory(
    f"{DATASET_PATH}/test",
    image_size=IMG_SIZE, batch_size=BATCH_SIZE, shuffle=False
)

class_names = train_raw.class_names
train_ds = train_raw.prefetch(AUTOTUNE)
valid_ds = valid_raw.prefetch(AUTOTUNE)
test_ds  = test_raw.prefetch(AUTOTUNE)

print("✅ Classes:", class_names)
print(f"   Train: {len(train_ds)} batches")
print(f"   Valid: {len(valid_ds)} batches")
print(f"   Test:  {len(test_ds)} batches")

# ── CNN V3 Training ────────────────────────────────────────
import numpy as np, mlflow, mlflow.keras
import matplotlib.pyplot as plt
import seaborn as sns
from sklearn.metrics import confusion_matrix, classification_report
from sklearn.utils.class_weight import compute_class_weight
from tensorflow.keras import layers, models, regularizers
from tensorflow.keras.callbacks import EarlyStopping, ReduceLROnPlateau

# Class weights
labels = []
for _, y in train_ds:
    labels.extend(y.numpy())
labels = np.array(labels)
cw = compute_class_weight("balanced", classes=np.unique(labels), y=labels)
class_weights = dict(enumerate(cw))
print("Class weights:", class_weights)

# Build model
reg = regularizers.l2(1e-4)

model_v3 = models.Sequential([
    layers.Rescaling(1./255, input_shape=(224, 224, 3)),

    # Block 1
    layers.Conv2D(32, (3,3), activation='relu',
                  padding='same', kernel_regularizer=reg),
    layers.BatchNormalization(),
    layers.Conv2D(32, (3,3), activation='relu',
                  padding='same', kernel_regularizer=reg),
    layers.MaxPooling2D(),
    layers.Dropout(0.25),

    # Block 2
    layers.Conv2D(64, (3,3), activation='relu',
                  padding='same', kernel_regularizer=reg),
    layers.BatchNormalization(),
    layers.Conv2D(64, (3,3), activation='relu',
                  padding='same', kernel_regularizer=reg),
    layers.MaxPooling2D(),
    layers.Dropout(0.25),

    # Block 3
    layers.Conv2D(128, (3,3), activation='relu',
                  padding='same', kernel_regularizer=reg),
    layers.BatchNormalization(),
    layers.Conv2D(128, (3,3), activation='relu',
                  padding='same', kernel_regularizer=reg),
    layers.MaxPooling2D(),
    layers.Dropout(0.3),

    layers.GlobalAveragePooling2D(),
    layers.Dense(128, activation='relu', kernel_regularizer=reg),
    layers.BatchNormalization(),
    layers.Dropout(0.5),
    layers.Dense(4, activation='softmax')
])

model_v3.compile(
    optimizer=tf.keras.optimizers.Adam(1e-3),
    loss='sparse_categorical_crossentropy',
    metrics=['accuracy']
)
model_v3.summary()

callbacks = [
    EarlyStopping(
        monitor='val_accuracy',
        patience=10,
        restore_best_weights=True,
        verbose=1
    ),
    ReduceLROnPlateau(
        monitor='val_loss',
        factor=0.5,
        patience=4,
        min_lr=1e-6,
        verbose=1
    )
]

# Train
print("\n🚀 Training CNN V3 on GPU...")
history_v3 = model_v3.fit(
    train_ds,
    validation_data=valid_ds,
    epochs=50,
    class_weight=class_weights,
    callbacks=callbacks
)

# Evaluate
test_loss, test_acc = model_v3.evaluate(test_ds, verbose=0)

y_true, y_pred = [], []
for images, lbls in test_ds:
    preds = model_v3.predict(images, verbose=0)
    y_true.extend(lbls.numpy())
    y_pred.extend(np.argmax(preds, axis=1))

report   = classification_report(
    y_true, y_pred, target_names=class_names, output_dict=True)
cm       = confusion_matrix(y_true, y_pred)
macro_f1 = report['macro avg']['f1-score']

print(f"\nTest Accuracy : {test_acc:.2%}")
print(f"Test Loss     : {test_loss:.4f}")
print(f"Macro F1      : {macro_f1:.2%}")
print(classification_report(y_true, y_pred, target_names=class_names))

# Plots
fig, axes = plt.subplots(1, 3, figsize=(18, 5))
fig.suptitle(f'CNN V3 — Acc:{test_acc:.2%}  F1:{macro_f1:.2%}',
             fontsize=14, fontweight='bold')

axes[0].plot(history_v3.history['accuracy'],     label='Train')
axes[0].plot(history_v3.history['val_accuracy'], label='Val')
axes[0].set_title('Accuracy')
axes[0].set_xlabel('Epoch')
axes[0].legend()

axes[1].plot(history_v3.history['loss'],     label='Train')
axes[1].plot(history_v3.history['val_loss'], label='Val')
axes[1].set_title('Loss')
axes[1].set_xlabel('Epoch')
axes[1].legend()

sns.heatmap(cm, annot=True, fmt='d', cmap='Blues',
            xticklabels=class_names,
            yticklabels=class_names, ax=axes[2])
axes[2].set_title('Confusion Matrix')
axes[2].set_ylabel('True')
axes[2].set_xlabel('Predicted')

plt.tight_layout()
plot_path = '/content/cnn_v3_results.png'
plt.savefig(plot_path, bbox_inches='tight', dpi=150)
plt.show()

# Save
model_v3.save('/content/drive/MyDrive/CNN_V3_Clean.keras')
print("✅ Model saved!")

# MLflow
mlflow.set_tracking_uri("sqlite:////content/mlflow.db")
mlflow.set_experiment("Capacitor_Orientation")

with mlflow.start_run(run_name="CNN_V3_Aug18_80split"):
    mlflow.log_param("model",         "CNN_V3")
    mlflow.log_param("img_size",      "224x224")
    mlflow.log_param("batch_size",    16)
    mlflow.log_param("epochs_run",    len(history_v3.history['accuracy']))
    mlflow.log_param("optimizer",     "Adam_1e-3")
    mlflow.log_param("dropout",       "0.25/0.25/0.3/0.5")
    mlflow.log_param("l2_reg",        "1e-4")
    mlflow.log_param("batch_norm",    "True")
    mlflow.log_param("class_weights", "True")
    mlflow.log_param("train_images",  2945)
    mlflow.log_param("valid_images",  19)
    mlflow.log_param("test_images",   19)
    mlflow.log_param("aug_variants",  18)
    mlflow.log_param("split",         "80_10_10")

    mlflow.log_metric("test_accuracy", test_acc)
    mlflow.log_metric("test_loss",     test_loss)
    mlflow.log_metric("macro_f1",      macro_f1)

    for cls in class_names:
        mlflow.log_metric(f"{cls}_f1",        report[cls]['f1-score'])
        mlflow.log_metric(f"{cls}_precision", report[cls]['precision'])
        mlflow.log_metric(f"{cls}_recall",    report[cls]['recall'])

    mlflow.log_artifact(plot_path)
    mlflow.keras.log_model(model_v3, "cnn_v3_model")

    print(f"✅ CNN V3 logged to MLflow!")
    print(f"   Test Accuracy : {test_acc:.2%}")
    print(f"   Macro F1      : {macro_f1:.2%}")

