# MODEL COMPARISON DASHBOARD
# ═══════════════════════════════════════════════════════════
import mlflow, pandas as pd
import matplotlib.pyplot as plt
import matplotlib.patches as mpatches
import numpy as np

mlflow.set_tracking_uri("sqlite:////content/mlflow.db")
client = mlflow.tracking.MlflowClient()

# Collect all runs
rows = []
for exp in client.search_experiments():
    for run in client.search_runs(experiment_ids=[exp.experiment_id]):
        m = run.data.metrics
        p = run.data.params
        rows.append({
            "Model":       run.info.run_name,
            "Accuracy":    m.get("test_accuracy", 0),
            "Macro F1":    m.get("macro_f1", 0),
            "Loss":        m.get("test_loss", 0),
            "Epochs":      p.get("epochs_run", "?"),
            "Img Size":    p.get("img_size", "224x224"),
            "Batch Size":  p.get("batch_size", "?"),
            "Dropout":     p.get("dropout", "None"),
            "L2 Reg":      p.get("l2_reg", "None"),
            "Aug":         p.get("aug_variants", "?"),
            "Split":       p.get("split", "?"),
            "Bottom F1":   m.get("Bottom_f1", 0),
            "Left F1":     m.get("Left_f1", 0),
            "Right F1":    m.get("Right_f1", 0),
            "Top F1":      m.get("Top_f1", 0),
        })

df = pd.DataFrame(rows).sort_values("Accuracy", ascending=False).reset_index(drop=True)
df["Rank"] = range(1, len(df)+1)

# ── Print table ────────────────────────────────────────────
print("=" * 80)
print("🏆  MODEL COMPARISON DASHBOARD")
print("=" * 80)
print(df[["Rank","Model","Accuracy","Macro F1",
          "Loss","Epochs","Dropout","L2 Reg"]].to_string(index=False))

print("\n📊 Per-Class F1:")
print(df[["Model","Bottom F1","Left F1",
          "Right F1","Top F1"]].to_string(index=False))

best = df.iloc[0]
print(f"\n🥇 Best Model : {best['Model']}")
print(f"   Accuracy   : {best['Accuracy']:.2%}")
print(f"   Macro F1   : {best['Macro F1']:.2%}")

# ── Visual Dashboard ───────────────────────────────────────
fig, axes = plt.subplots(2, 2, figsize=(16, 12))
fig.suptitle('🏆 Model Comparison Dashboard — Capacitor Orientation',
             fontsize=16, fontweight='bold')

model_labels = [m.replace("_DataV3_Clean","").replace("_Aug18_80split","")
                for m in df["Model"].tolist()]
colors = ['gold' if i==0 else 'steelblue' for i in range(len(model_labels))]

# 1. Accuracy
bars = axes[0,0].barh(model_labels, df["Accuracy"]*100, color=colors)
axes[0,0].set_xlabel("Test Accuracy (%)")
axes[0,0].set_title("Test Accuracy")
axes[0,0].set_xlim(0, 105)
for i, v in enumerate(df["Accuracy"]):
    axes[0,0].text(v*100+0.5, i, f"{v:.2%}", va='center', fontsize=9)

# 2. Macro F1
axes[0,1].barh(model_labels, df["Macro F1"]*100, color=colors)
axes[0,1].set_xlabel("Macro F1 (%)")
axes[0,1].set_title("Macro F1 Score")
axes[0,1].set_xlim(0, 105)
for i, v in enumerate(df["Macro F1"]):
    axes[0,1].text(v*100+0.5, i, f"{v:.2%}", va='center', fontsize=9)

# 3. Per-class F1
x = np.arange(len(model_labels))
w = 0.2
cls_colors = ['#e74c3c','#3498db','#2ecc71','#f39c12']
for i, (cls, col) in enumerate(zip(
        ["Bottom F1","Left F1","Right F1","Top F1"], cls_colors)):
    axes[1,0].bar(x + i*w, df[cls]*100, w,
                  label=cls.replace(" F1",""), color=col)
axes[1,0].set_xticks(x + w*1.5)
axes[1,0].set_xticklabels(model_labels, rotation=15, ha='right', fontsize=8)
axes[1,0].set_title("Per-Class F1 Score")
axes[1,0].set_ylabel("F1 (%)")
axes[1,0].legend()

# 4. Accuracy vs Loss scatter
scatter_colors = ['gold' if i==0 else 'steelblue'
                  for i in range(len(df))]
axes[1,1].scatter(df["Loss"], df["Accuracy"]*100,
                  c=scatter_colors, s=250, zorder=5, edgecolors='black')
for _, row in df.iterrows():
    label = row["Model"].replace("_DataV3_Clean","").replace("_Aug18_80split","")
    axes[1,1].annotate(label,
        (row["Loss"], row["Accuracy"]*100),
        textcoords="offset points", xytext=(6,4), fontsize=8)
axes[1,1].set_xlabel("Test Loss (lower = better)")
axes[1,1].set_ylabel("Test Accuracy (%)")
axes[1,1].set_title("Accuracy vs Loss\n(top-left = best)")
gold_patch = mpatches.Patch(color='gold', label='🥇 Best Model')
axes[1,1].legend(handles=[gold_patch])

plt.tight_layout()
dashboard_path = '/content/drive/MyDrive/model_dashboard.png'
plt.savefig(dashboard_path, bbox_inches='tight', dpi=150)
plt.show()
print(f"\n✅ Dashboard saved to Drive!")

# ═══════════════════════════════════════════════════════════
# MobileNetV2 — Correct augmented dataset (already ready!)
# ═══════════════════════════════════════════════════════════
import numpy as np, mlflow, mlflow.keras, os
import matplotlib.pyplot as plt
import seaborn as sns
import tensorflow as tf
from tensorflow.keras import layers, models
from tensorflow.keras.callbacks import EarlyStopping, ReduceLROnPlateau, ModelCheckpoint
from sklearn.metrics import confusion_matrix, classification_report
from sklearn.utils.class_weight import compute_class_weight

# ── Class weights ──────────────────────────────────────────
labels = []
for _, y in train_ds:
    labels.extend(y.numpy())
labels = np.array(labels)
cw = compute_class_weight("balanced", classes=np.unique(labels), y=labels)
class_weights = dict(enumerate(cw))
print("Class weights:", class_weights)

# ── Build MobileNetV2 ──────────────────────────────────────
base_model = tf.keras.applications.MobileNetV2(
    input_shape=(224, 224, 3),
    include_top=False,
    weights='imagenet'
)
base_model.trainable = False  # Freeze for Phase 1
print(f"Base model layers: {len(base_model.layers)}")

model_mobilenet_v2 = models.Sequential([
    layers.Input(shape=(224, 224, 3)),
    layers.Rescaling(1./127.5, offset=-1),  # MobileNet needs [-1, 1]
    base_model,
    layers.GlobalAveragePooling2D(),
    layers.BatchNormalization(),
    layers.Dense(128, activation='relu'),
    layers.Dropout(0.4),
    layers.Dense(64, activation='relu'),
    layers.Dropout(0.3),
    layers.Dense(4, activation='softmax')
])

model_mobilenet_v2.compile(
    optimizer=tf.keras.optimizers.Adam(1e-3),
    loss='sparse_categorical_crossentropy',
    metrics=['accuracy']
)
model_mobilenet_v2.summary()

# ── PHASE 1: Train top layers only ────────────────────────
print("\n🚀 Phase 1: Training top layers (base frozen)...")

callbacks_p1 = [
    EarlyStopping(
        monitor='val_accuracy',
        patience=5,
        restore_best_weights=True,
        verbose=1
    )
]

history_p1 = model_mobilenet_v2.fit(
    train_ds,
    validation_data=valid_ds,
    epochs=15,
    class_weight=class_weights,
    callbacks=callbacks_p1
)

print(f"\nPhase 1 done!")
print(f"  Best val accuracy: {max(history_p1.history['val_accuracy']):.2%}")

# ── PHASE 2: Fine-tune last 40 layers ─────────────────────
print("\n🔓 Phase 2: Fine-tuning last 40 layers...")

base_model.trainable = True
for layer in base_model.layers[:-40]:
    layer.trainable = False

trainable_count = sum(1 for l in base_model.layers if l.trainable)
print(f"  Trainable base layers: {trainable_count}")

model_mobilenet_v2.compile(
    optimizer=tf.keras.optimizers.Adam(1e-5),  # Much lower LR
    loss='sparse_categorical_crossentropy',
    metrics=['accuracy']
)

callbacks_p2 = [
    EarlyStopping(
        monitor='val_accuracy',
        patience=8,
        restore_best_weights=True,
        verbose=1
    ),
    ReduceLROnPlateau(
        monitor='val_loss',
        factor=0.5,
        patience=3,
        min_lr=1e-7,
        verbose=1
    ),
    ModelCheckpoint(
        '/content/drive/MyDrive/MobileNetV2_best.keras',
        monitor='val_accuracy',
        save_best_only=True,
        verbose=1
    )
]

history_p2 = model_mobilenet_v2.fit(
    train_ds,
    validation_data=valid_ds,
    epochs=30,
    class_weight=class_weights,
    callbacks=callbacks_p2
)

# ── Evaluate ───────────────────────────────────────────────
print("\nEvaluating on test set...")
test_loss, test_acc = model_mobilenet_v2.evaluate(test_ds, verbose=0)

y_true, y_pred = [], []
for images, lbls in test_ds:
    preds = model_mobilenet_v2.predict(images, verbose=0)
    y_true.extend(lbls.numpy())
    y_pred.extend(np.argmax(preds, axis=1))

report   = classification_report(
    y_true, y_pred, target_names=class_names, output_dict=True)
cm       = confusion_matrix(y_true, y_pred)
macro_f1 = report['macro avg']['f1-score']

print(f"\nTest Accuracy : {test_acc:.2%}")
print(f"Test Loss     : {test_loss:.4f}")
print(f"Macro F1      : {macro_f1:.2%}")
print(classification_report(y_true, y_pred, target_names=class_names))

# ── Plots ──────────────────────────────────────────────────
# Combine both phases
acc    = history_p1.history['accuracy']    + history_p2.history['accuracy']
val    = history_p1.history['val_accuracy']+ history_p2.history['val_accuracy']
loss   = history_p1.history['loss']        + history_p2.history['loss']
v_loss = history_p1.history['val_loss']    + history_p2.history['val_loss']
p1_end = len(history_p1.history['accuracy'])

fig, axes = plt.subplots(1, 3, figsize=(18, 5))
fig.suptitle(f'MobileNetV2 — Acc:{test_acc:.2%}  F1:{macro_f1:.2%}',
             fontsize=14, fontweight='bold')

axes[0].plot(acc,  label='Train')
axes[0].plot(val,  label='Val')
axes[0].axvline(x=p1_end, color='red',
                linestyle='--', label='Fine-tune start')
axes[0].set_title('Accuracy')
axes[0].set_xlabel('Epoch')
axes[0].legend()

axes[1].plot(loss,   label='Train')
axes[1].plot(v_loss, label='Val')
axes[1].axvline(x=p1_end, color='red',
                linestyle='--', label='Fine-tune start')
axes[1].set_title('Loss')
axes[1].set_xlabel('Epoch')
axes[1].legend()

sns.heatmap(cm, annot=True, fmt='d', cmap='Blues',
            xticklabels=class_names,
            yticklabels=class_names, ax=axes[2])
axes[2].set_title('Confusion Matrix')
axes[2].set_ylabel('True')
axes[2].set_xlabel('Predicted')

plt.tight_layout()
plot_path = '/content/mobilenetv2_results.png'
plt.savefig(plot_path, bbox_inches='tight', dpi=150)
plt.show()

# ── Save final model ───────────────────────────────────────
model_mobilenet_v2.save('/content/drive/MyDrive/MobileNetV2_Clean.keras')
print("✅ Final model saved!")

# ── MLflow ─────────────────────────────────────────────────
mlflow.set_tracking_uri("sqlite:////content/mlflow.db")
mlflow.set_experiment("Capacitor_Orientation")

total_epochs = len(acc)

with mlflow.start_run(run_name="MobileNetV2_Aug18_80split"):
    mlflow.log_param("model",           "MobileNetV2")
    mlflow.log_param("img_size",        "224x224")
    mlflow.log_param("batch_size",      16)
    mlflow.log_param("epochs_run",      total_epochs)
    mlflow.log_param("phase1_epochs",   len(history_p1.history['accuracy']))
    mlflow.log_param("phase2_epochs",   len(history_p2.history['accuracy']))
    mlflow.log_param("optimizer_p1",    "Adam_1e-3")
    mlflow.log_param("optimizer_p2",    "Adam_1e-5")
    mlflow.log_param("dropout",         "0.4/0.3")
    mlflow.log_param("frozen_layers",   "all_except_last_40")
    mlflow.log_param("base_model",      "MobileNetV2_imagenet")
    mlflow.log_param("class_weights",   "True")
    mlflow.log_param("train_images",    2945)
    mlflow.log_param("aug_variants",    18)
    mlflow.log_param("split",           "80_10_10")

    mlflow.log_metric("test_accuracy",  test_acc)
    mlflow.log_metric("test_loss",      test_loss)
    mlflow.log_metric("macro_f1",       macro_f1)

    for cls in class_names:
        mlflow.log_metric(f"{cls}_f1",        report[cls]['f1-score'])
        mlflow.log_metric(f"{cls}_precision", report[cls]['precision'])
        mlflow.log_metric(f"{cls}_recall",    report[cls]['recall'])

    mlflow.log_artifact(plot_path)
    mlflow.keras.log_model(model_mobilenet_v2, "mobilenetv2_model")

    print(f"✅ MobileNetV2 logged to MLflow!")
    print(f"   Test Accuracy : {test_acc:.2%}")
    print(f"   Macro F1      : {macro_f1:.2%}")

# ═══════════════════════════════════════════════════════════
# MLFLOW SUMMARY TABLE + DASHBOARD
# ═══════════════════════════════════════════════════════════
import mlflow, pandas as pd
import matplotlib.pyplot as plt
import matplotlib.patches as mpatches
import numpy as np

mlflow.set_tracking_uri("sqlite:////content/mlflow.db")
client = mlflow.tracking.MlflowClient()

# Collect all runs
rows = []
for exp in client.search_experiments():
    for run in client.search_runs(experiment_ids=[exp.experiment_id]):
        m = run.data.metrics
        p = run.data.params
        rows.append({
            "Model":        run.info.run_name,
            "Accuracy %":   round(m.get("test_accuracy", 0)*100, 2),
            "Macro F1 %":   round(m.get("macro_f1", 0)*100, 2),
            "Loss":         round(m.get("test_loss", 0), 4),
            "Epochs":       p.get("epochs_run", "?"),
            "Train Images": p.get("train_images", "?"),
            "Img Size":     p.get("img_size", "224x224"),
            "Batch Size":   p.get("batch_size", "?"),
            "Dropout":      p.get("dropout", "None"),
            "L2 Reg":       p.get("l2_reg", "None"),
            "Aug Variants": p.get("aug_variants", "?"),
            "Split":        p.get("split", "?"),
            "Bottom F1":    round(m.get("Bottom_f1", 0)*100, 1),
            "Left F1":      round(m.get("Left_f1", 0)*100, 1),
            "Right F1":     round(m.get("Right_f1", 0)*100, 1),
            "Top F1":       round(m.get("Top_f1", 0)*100, 1),
        })

df = pd.DataFrame(rows).sort_values("Accuracy %", ascending=False).reset_index(drop=True)
df.insert(0, "Rank", ["🥇","🥈","🥉"] + [f"#{i}" for i in range(4, len(df)+1)])

# ── Print full table ───────────────────────────────────────
print("=" * 90)
print("🏆  FULL MODEL COMPARISON TABLE")
print("=" * 90)
pd.set_option('display.max_columns', None)
pd.set_option('display.width', 200)
print(df[["Rank","Model","Accuracy %","Macro F1 %","Loss",
          "Epochs","Train Images","Batch Size",
          "Dropout","L2 Reg","Aug Variants"]].to_string(index=False))

print("\n📊 Per-Class F1 (%):")
print(df[["Rank","Model","Bottom F1","Left F1",
          "Right F1","Top F1"]].to_string(index=False))

best = df.iloc[0]
print(f"\n🥇 BEST MODEL : {best['Model']}")
print(f"   Accuracy   : {best['Accuracy %']}%")
print(f"   Macro F1   : {best['Macro F1 %']}%")
print(f"   Loss       : {best['Loss']}")

# ── Visual Dashboard ───────────────────────────────────────
fig, axes = plt.subplots(2, 2, figsize=(18, 12))
fig.suptitle('🏆 Model Comparison Dashboard — Capacitor Orientation',
             fontsize=16, fontweight='bold')

labels = [m.replace("_DataV3_Clean","")
           .replace("_Aug18_80split","")
           .replace("_AugV4_Clean","")
          for m in df["Model"].tolist()]
colors = ['gold','silver','#cd7f32'] + ['steelblue']*(len(labels)-3)

# 1. Accuracy
axes[0,0].barh(labels, df["Accuracy %"], color=colors, edgecolor='black')
axes[0,0].set_xlabel("Test Accuracy (%)")
axes[0,0].set_title("Test Accuracy", fontweight='bold')
axes[0,0].set_xlim(0, 110)
for i, v in enumerate(df["Accuracy %"]):
    axes[0,0].text(v+0.5, i, f"{v}%", va='center', fontsize=9)

# 2. Macro F1
axes[0,1].barh(labels, df["Macro F1 %"], color=colors, edgecolor='black')
axes[0,1].set_xlabel("Macro F1 (%)")
axes[0,1].set_title("Macro F1 Score", fontweight='bold')
axes[0,1].set_xlim(0, 110)
for i, v in enumerate(df["Macro F1 %"]):
    axes[0,1].text(v+0.5, i, f"{v}%", va='center', fontsize=9)

# 3. Per-class F1
x = np.arange(len(labels))
w = 0.2
cls_colors = ['#e74c3c','#3498db','#2ecc71','#f39c12']
for i, (cls, col) in enumerate(zip(
        ["Bottom F1","Left F1","Right F1","Top F1"], cls_colors)):
    axes[1,0].bar(x + i*w, df[cls], w, label=cls.replace(" F1",""), color=col)
axes[1,0].set_xticks(x + w*1.5)
axes[1,0].set_xticklabels(labels, rotation=15, ha='right', fontsize=8)
axes[1,0].set_title("Per-Class F1 Score (%)", fontweight='bold')
axes[1,0].set_ylabel("F1 (%)")
axes[1,0].legend()

# 4. Accuracy vs Loss
axes[1,1].scatter(df["Loss"], df["Accuracy %"],
                  c=colors, s=300, zorder=5, edgecolors='black')
for _, row in df.iterrows():
    lbl = row["Model"].replace("_DataV3_Clean","") \
                      .replace("_Aug18_80split","") \
                      .replace("_AugV4_Clean","")
    axes[1,1].annotate(lbl,
        (row["Loss"], row["Accuracy %"]),
        textcoords="offset points", xytext=(6,4), fontsize=8)
axes[1,1].set_xlabel("Test Loss (lower = better)")
axes[1,1].set_ylabel("Test Accuracy (%)")
axes[1,1].set_title("Accuracy vs Loss\n(top-left = best)", fontweight='bold')
gold_p   = mpatches.Patch(color='gold',   label='🥇 1st')
silver_p = mpatches.Patch(color='silver', label='🥈 2nd')
bronze_p = mpatches.Patch(color='#cd7f32',label='🥉 3rd')
axes[1,1].legend(handles=[gold_p, silver_p, bronze_p])

plt.tight_layout()
dashboard_path = '/content/drive/MyDrive/model_dashboard.png'
plt.savefig(dashboard_path, bbox_inches='tight', dpi=150)
plt.show()
print(f"✅ Dashboard saved to Drive!")

