import os
import mlflow
import tensorflow as tf
import numpy as np

from sklearn.metrics import (
    classification_report,
    f1_score,
    confusion_matrix
)

# ──────────────────────────────────────────────
# MLflow DB
# ──────────────────────────────────────────────
mlflow.set_tracking_uri("sqlite:////content/mlflow.db")
mlflow.set_experiment("Capacitor_Polarity_Detection")

# ──────────────────────────────────────────────
# Dataset
# ──────────────────────────────────────────────
DATASET_PATH = "/content/final_dataset"

IMG_SIZE = (224,224)
BATCH_SIZE = 32

test_ds = tf.keras.preprocessing.image_dataset_from_directory(
    f"{DATASET_PATH}/test",
    image_size=IMG_SIZE,
    batch_size=BATCH_SIZE,
    shuffle=False
)

class_names = test_ds.class_names

print("Classes:", class_names)

# ──────────────────────────────────────────────
# Models to evaluate
# ──────────────────────────────────────────────
MODELS = [
    "best_capacitor_cnn.keras",
    "mobilenet_frozen.keras",
    "mobilenet_193_dataset.keras",
    "mobilenet_frozen_76.keras",
    "best_model.keras",
    "CNN_V1_Clean.keras",
    "CNN_V2_Clean.keras",
    "CNN_V3_Clean.keras",
    "MobileNetV2_best.keras",
    "MobileNetV2_Clean.keras"
]

# ──────────────────────────────────────────────
# Evaluate + Log
# ──────────────────────────────────────────────
for model_file in MODELS:

    model_path = f"/content/drive/MyDrive/{model_file}"

    if not os.path.exists(model_path):
        print(f"Skipping: {model_file}")
        continue

    print("\n" + "="*70)
    print("Evaluating:", model_file)
    print("="*70)

    try:

        model = tf.keras.models.load_model(
            model_path,
            compile=False
        )

        model.compile(
            optimizer="adam",
            loss="sparse_categorical_crossentropy",
            metrics=["accuracy"]
        )

        test_loss, test_acc = model.evaluate(
            test_ds,
            verbose=0
        )

        y_true = []
        y_pred = []

        for images, labels in test_ds:

            preds = model.predict(
                images,
                verbose=0
            )

            y_true.extend(labels.numpy())
            y_pred.extend(
                np.argmax(preds, axis=1)
            )

        report = classification_report(
            y_true,
            y_pred,
            target_names=class_names,
            output_dict=True
        )

        macro_f1 = f1_score(
            y_true,
            y_pred,
            average="macro"
        )

        with mlflow.start_run(
            run_name=model_file.replace(".keras","")
        ):

            mlflow.log_param(
                "model_name",
                model_file
            )

            mlflow.log_metric(
                "test_accuracy",
                float(test_acc)
            )

            mlflow.log_metric(
                "test_loss",
                float(test_loss)
            )

            mlflow.log_metric(
                "macro_f1",
                float(macro_f1)
            )

            for cls in class_names:

                mlflow.log_metric(
                    f"{cls}_precision",
                    report[cls]["precision"]
                )

                mlflow.log_metric(
                    f"{cls}_recall",
                    report[cls]["recall"]
                )

                mlflow.log_metric(
                    f"{cls}_f1",
                    report[cls]["f1-score"]
                )

        print(
            f"Logged ✓  Acc={test_acc:.4f}  MacroF1={macro_f1:.4f}"
        )

    except Exception as e:
        print(f"ERROR: {model_file}")
        print(e)

print("\nDONE!")

