# ═══════════════════════════════════════════════════════════
# EfficientNetB0 Training
# ═══════════════════════════════════════════════════════════
import numpy as np, mlflow, mlflow.keras, os
import matplotlib.pyplot as plt
import seaborn as sns
import tensorflow as tf
from tensorflow.keras import layers, models
from tensorflow.keras.callbacks import EarlyStopping, ReduceLROnPlateau, ModelCheckpoint
from sklearn.metrics import confusion_matrix, classification_report
from sklearn.utils.class_weight import compute_class_weight

# ── Class weights ──────────────────────────────────────────
labels = []
for _, y in train_ds:
    labels.extend(y.numpy())
labels = np.array(labels)
cw = compute_class_weight("balanced", classes=np.unique(labels), y=labels)
class_weights = dict(enumerate(cw))
print("Class weights:", class_weights)

# ── Build EfficientNetB0 ───────────────────────────────────
base_model = tf.keras.applications.EfficientNetB0(
    input_shape=(224, 224, 3),
    include_top=False,
    weights='imagenet'
)
base_model.trainable = False
print(f"✅ EfficientNetB0 — {len(base_model.layers)} layers")

model_eff = models.Sequential([
    layers.Input(shape=(224, 224, 3)),
    base_model,
    layers.GlobalAveragePooling2D(),
    layers.BatchNormalization(),
    layers.Dense(256, activation='relu'),
    layers.Dropout(0.4),
    layers.Dense(128, activation='relu'),
    layers.Dropout(0.3),
    layers.Dense(4, activation='softmax')
])

model_eff.compile(
    optimizer=tf.keras.optimizers.Adam(1e-3),
    loss='sparse_categorical_crossentropy',
    metrics=['accuracy']
)
model_eff.summary()

# ── PHASE 1: Train head only ───────────────────────────────
print("\n🚀 Phase 1: Head training (base frozen)...")

history_p1 = model_eff.fit(
    train_ds,
    validation_data=valid_ds,
    epochs=15,
    class_weight=class_weights,
    callbacks=[
        EarlyStopping(
            monitor='val_accuracy',
            patience=5,
            restore_best_weights=True,
            verbose=1
        )
    ]
)
print(f"✅ Phase 1 done! Best val: {max(history_p1.history['val_accuracy']):.2%}")

# ── PHASE 2: Fine-tune last 30 layers ─────────────────────
print("\n🔓 Phase 2: Fine-tuning last 30 layers...")

base_model.trainable = True
for layer in base_model.layers[:-30]:
    layer.trainable = False

model_eff.compile(
    optimizer=tf.keras.optimizers.Adam(1e-5),
    loss='sparse_categorical_crossentropy',
    metrics=['accuracy']
)

history_p2 = model_eff.fit(
    train_ds,
    validation_data=valid_ds,
    epochs=30,
    class_weight=class_weights,
    callbacks=[
        EarlyStopping(
            monitor='val_accuracy',
            patience=8,
            restore_best_weights=True,
            verbose=1
        ),
        ReduceLROnPlateau(
            monitor='val_loss',
            factor=0.5,
            patience=3,
            min_lr=1e-7,
            verbose=1
        ),
        ModelCheckpoint(
            '/content/drive/MyDrive/EfficientNetB0_best.keras',
            monitor='val_accuracy',
            save_best_only=True,
            verbose=1
        )
    ]
)

# ── Evaluate ───────────────────────────────────────────────
test_loss, test_acc = model_eff.evaluate(test_ds, verbose=0)

y_true, y_pred = [], []
for images, lbls in test_ds:
    preds = model_eff.predict(images, verbose=0)
    y_true.extend(lbls.numpy())
    y_pred.extend(np.argmax(preds, axis=1))

report   = classification_report(
    y_true, y_pred, target_names=class_names, output_dict=True)
cm       = confusion_matrix(y_true, y_pred)
macro_f1 = report['macro avg']['f1-score']

print(f"\nTest Accuracy : {test_acc:.2%}")
print(f"Test Loss     : {test_loss:.4f}")
print(f"Macro F1      : {macro_f1:.2%}")
print(classification_report(y_true, y_pred, target_names=class_names))

# ── Plots ──────────────────────────────────────────────────
acc    = history_p1.history['accuracy']     + history_p2.history['accuracy']
val    = history_p1.history['val_accuracy'] + history_p2.history['val_accuracy']
loss   = history_p1.history['loss']         + history_p2.history['loss']
v_loss = history_p1.history['val_loss']     + history_p2.history['val_loss']
p1_end = len(history_p1.history['accuracy'])

fig, axes = plt.subplots(1, 3, figsize=(18, 5))
fig.suptitle(f'EfficientNetB0 — Acc:{test_acc:.2%}  F1:{macro_f1:.2%}',
             fontsize=14, fontweight='bold')

axes[0].plot(acc,  label='Train')
axes[0].plot(val,  label='Val')
axes[0].axvline(x=p1_end, color='red',
                linestyle='--', label='Fine-tune start')
axes[0].set_title('Accuracy')
axes[0].set_xlabel('Epoch')
axes[0].legend()

axes[1].plot(loss,   label='Train')
axes[1].plot(v_loss, label='Val')
axes[1].axvline(x=p1_end, color='red',
                linestyle='--', label='Fine-tune start')
axes[1].set_title('Loss')
axes[1].set_xlabel('Epoch')
axes[1].legend()

sns.heatmap(cm, annot=True, fmt='d', cmap='Blues',
            xticklabels=class_names,
            yticklabels=class_names, ax=axes[2])
axes[2].set_title('Confusion Matrix')
axes[2].set_ylabel('True')
axes[2].set_xlabel('Predicted')

plt.tight_layout()
plot_path = '/content/efficientnetb0_results.png'
plt.savefig(plot_path, bbox_inches='tight', dpi=150)
plt.show()

# ── Save ───────────────────────────────────────────────────
model_eff.save('/content/drive/MyDrive/EfficientNetB0_Clean.keras')
print("✅ Model saved!")

# ── MLflow ─────────────────────────────────────────────────
mlflow.set_tracking_uri("sqlite:////content/mlflow.db")
mlflow.set_experiment("Capacitor_Orientation")

total_epochs = len(acc)

with mlflow.start_run(run_name="EfficientNetB0_Aug18_80split"):
    mlflow.log_param("model",          "EfficientNetB0")
    mlflow.log_param("img_size",       "224x224")
    mlflow.log_param("batch_size",     16)
    mlflow.log_param("epochs_run",     total_epochs)
    mlflow.log_param("phase1_epochs",  len(history_p1.history['accuracy']))
    mlflow.log_param("phase2_epochs",  len(history_p2.history['accuracy']))
    mlflow.log_param("optimizer_p1",   "Adam_1e-3")
    mlflow.log_param("optimizer_p2",   "Adam_1e-5")
    mlflow.log_param("dropout",        "0.4/0.3")
    mlflow.log_param("frozen_layers",  "all_except_last_30")
    mlflow.log_param("base_model",     "EfficientNetB0_imagenet")
    mlflow.log_param("class_weights",  "True")
    mlflow.log_param("train_images",   2945)
    mlflow.log_param("valid_images",   19)
    mlflow.log_param("test_images",    19)
    mlflow.log_param("aug_variants",   18)
    mlflow.log_param("split",          "80_10_10")
    mlflow.log_param("architecture",   "EfficientNetB0+GAP+BN+Dense256+Dense128")

    mlflow.log_metric("test_accuracy", test_acc)
    mlflow.log_metric("test_loss",     test_loss)
    mlflow.log_metric("macro_f1",      macro_f1)

    for cls in class_names:
        mlflow.log_metric(f"{cls}_f1",        report[cls]['f1-score'])
        mlflow.log_metric(f"{cls}_precision", report[cls]['precision'])
        mlflow.log_metric(f"{cls}_recall",    report[cls]['recall'])

    mlflow.log_artifact(plot_path)
    mlflow.keras.log_model(model_eff, "efficientnetb0_model")

    print(f"✅ EfficientNetB0 logged to MLflow!")
    print(f"   Test Accuracy : {test_acc:.2%}")
    print(f"   Macro F1      : {macro_f1:.2%}")

