import subprocess, time, re, os

os.environ["MLFLOW_ALLOW_FILE_STORE"] = "true"

subprocess.run("fuser -k 5000/tcp", shell=True, capture_output=True)
subprocess.run(["pkill", "-f", "cloudflared"], capture_output=True)
time.sleep(2)

# Pass env variable to mlflow ui process
env = os.environ.copy()
env["MLFLOW_ALLOW_FILE_STORE"] = "true"

proc = subprocess.Popen(
    "MLFLOW_ALLOW_FILE_STORE=true mlflow ui "
    "--host 0.0.0.0 --port 5000 "
    "--backend-store-uri file:///content/mlruns "
    "> /tmp/mlflow.log 2>&1",
    shell=True, env=env
)

print("⏳ Waiting for MLflow...")
for i in range(25):
    time.sleep(2)
    try:
        with open("/tmp/mlflow.log") as f:
            log = f.read()
        if "Uvicorn running" in log or "Running on" in log:
            print("✅ MLflow is up!")
            break
        print(f"   waiting... ({i*2}s)")
    except:
        pass

tunnel = subprocess.Popen(
    ["./cloudflared", "tunnel", "--url", "http://localhost:5000"],
    stdout=subprocess.PIPE, stderr=subprocess.STDOUT
)
for _ in range(40):
    line = tunnel.stdout.readline().decode()
    if "trycloudflare.com" in line:
        url = re.search(r'https://\S+\.trycloudflare\.com', line)
        if url:
            print("=" * 55)
            print(f"🔗 MLflow UI → {url.group()}")
            print("=" * 55)
            print("Wait 15 seconds then click!")
            break
    time.sleep(0.5)

