# FULL DASHBOARD + TABLE — directly in Colab
# ═══════════════════════════════════════════════════════════
import pandas as pd
import matplotlib.pyplot as plt
import matplotlib.patches as mpatches
import numpy as np
import os, mlflow

os.environ["MLFLOW_ALLOW_FILE_STORE"] = "true"
mlflow.set_tracking_uri("file:///content/mlruns")
client = mlflow.tracking.MlflowClient()

# ── Collect all runs from MLflow ───────────────────────────
rows = []
for exp in client.search_experiments():
    for run in client.search_runs(experiment_ids=[exp.experiment_id]):
        m = run.data.metrics
        p = run.data.params
        rows.append({
            "Model":        run.info.run_name,
            "Accuracy %":   round(m.get("test_accuracy", 0)*100, 2),
            "Macro F1 %":   round(m.get("macro_f1", 0)*100, 2),
            "Loss":         round(m.get("test_loss", 0), 4),
            "Epochs":       p.get("epochs_run", "?"),
            "Train Images": p.get("train_images", "?"),
            "Batch Size":   p.get("batch_size", "?"),
            "Img Size":     p.get("img_size", "224x224"),
            "Dropout":      p.get("dropout", "None"),
            "L2 Reg":       p.get("l2_reg", "None"),
            "Aug Variants": p.get("aug_variants", "?"),
            "Split":        p.get("split", "?"),
            "Bottom F1":    round(m.get("Bottom_f1", 0)*100, 1),
            "Left F1":      round(m.get("Left_f1", 0)*100, 1),
            "Right F1":     round(m.get("Right_f1", 0)*100, 1),
            "Top F1":       round(m.get("Top_f1", 0)*100, 1),
        })

df = pd.DataFrame(rows).sort_values(
    "Accuracy %", ascending=False).reset_index(drop=True)
df.insert(0, "Rank", ["🥇","🥈","🥉","#4","#5"][:len(df)])

# ── TABLE 1: Main metrics ──────────────────────────────────
print("="*90)
print("🏆  MODEL COMPARISON TABLE")
print("="*90)
pd.set_option('display.max_columns', None)
pd.set_option('display.width', 200)
print(df[["Rank","Model","Accuracy %","Macro F1 %",
          "Loss","Epochs","Train Images",
          "Batch Size","Dropout","L2 Reg",
          "Aug Variants","Split"]].to_string(index=False))

# ── TABLE 2: Per-class F1 ──────────────────────────────────
print("\n📊 Per-Class F1 (%):")
print(df[["Rank","Model","Bottom F1","Left F1",
          "Right F1","Top F1"]].to_string(index=False))

# ── Best model summary ─────────────────────────────────────
best = df.iloc[0]
print(f"\n{'='*50}")
print(f"🥇 BEST MODEL  : {best['Model']}")
print(f"   Accuracy   : {best['Accuracy %']}%")
print(f"   Macro F1   : {best['Macro F1 %']}%")
print(f"   Loss       : {best['Loss']}")
print(f"   Epochs     : {best['Epochs']}")
print(f"   Train Imgs : {best['Train Images']}")
print(f"{'='*50}")

# ── Styled table with colors (HTML) ───────────────────────
from IPython.display import display, HTML

def color_accuracy(val):
    if val >= 78:   return 'background-color: #2ecc71; color: white'
    elif val >= 74: return 'background-color: #f39c12; color: white'
    else:           return 'background-color: #e74c3c; color: white'

def color_f1(val):
    if val >= 77:   return 'background-color: #2ecc71; color: white'
    elif val >= 71: return 'background-color: #f39c12; color: white'
    else:           return 'background-color: #e74c3c; color: white'

styled = df[["Rank","Model","Accuracy %","Macro F1 %",
             "Loss","Epochs","Train Images",
             "Bottom F1","Left F1","Right F1","Top F1"]]\
    .style\
    .applymap(color_accuracy, subset=["Accuracy %"])\
    .applymap(color_f1,       subset=["Macro F1 %",
                                       "Bottom F1","Left F1",
                                       "Right F1","Top F1"])\
    .set_properties(**{'text-align': 'center',
                        'font-size': '13px',
                        'border': '1px solid #ddd'})\
    .set_table_styles([{
        'selector': 'th',
        'props': [('background-color','#2c3e50'),
                  ('color','white'),
                  ('font-size','13px'),
                  ('text-align','center'),
                  ('padding','8px')]
    }])\
    .set_caption("🏆 Model Comparison — Capacitor Orientation")

print("\n📊 Colour-coded Table (🟢 good  🟡 ok  🔴 weak):")
display(styled)

# ── Visual Dashboard ───────────────────────────────────────
models = df["Model"].tolist()
colors = ['gold','gold','silver','#cd7f32','steelblue'][:len(models)]

fig, axes = plt.subplots(2, 2, figsize=(18, 12))
fig.suptitle('🏆 Model Comparison Dashboard — Capacitor Orientation',
             fontsize=16, fontweight='bold')

# 1. Accuracy
axes[0,0].barh(models, df["Accuracy %"], color=colors, edgecolor='black')
axes[0,0].set_xlabel("Test Accuracy (%)")
axes[0,0].set_title("Test Accuracy", fontweight='bold')
axes[0,0].set_xlim(0, 110)
for i, v in enumerate(df["Accuracy %"]):
    axes[0,0].text(v+0.5, i, f"{v}%", va='center', fontsize=10)

# 2. Macro F1
axes[0,1].barh(models, df["Macro F1 %"], color=colors, edgecolor='black')
axes[0,1].set_xlabel("Macro F1 (%)")
axes[0,1].set_title("Macro F1 Score", fontweight='bold')
axes[0,1].set_xlim(0, 110)
for i, v in enumerate(df["Macro F1 %"]):
    axes[0,1].text(v+0.5, i, f"{v}%", va='center', fontsize=10)

# 3. Per-class F1
x = np.arange(len(models))
w = 0.2
cls_colors = ['#e74c3c','#3498db','#2ecc71','#f39c12']
for i,(cls,col) in enumerate(zip(
        ["Bottom F1","Left F1","Right F1","Top F1"], cls_colors)):
    axes[1,0].bar(x+i*w, df[cls], w,
                  label=cls.replace(" F1",""), color=col)
axes[1,0].set_xticks(x+w*1.5)
axes[1,0].set_xticklabels(models, rotation=15, ha='right', fontsize=9)
axes[1,0].set_title("Per-Class F1 Score (%)", fontweight='bold')
axes[1,0].set_ylabel("F1 (%)")
axes[1,0].set_ylim(0, 110)
axes[1,0].legend()
for bar in axes[1,0].patches:
    h = bar.get_height()
    if h > 0:
        axes[1,0].text(
            bar.get_x() + bar.get_width()/2,
            h+1, f"{h:.0f}", ha='center', fontsize=7)

# 4. Accuracy vs Loss scatter
axes[1,1].scatter(df["Loss"], df["Accuracy %"],
                  c=colors, s=300, zorder=5, edgecolors='black')
for _, row in df.iterrows():
    axes[1,1].annotate(
        row["Model"],
        (row["Loss"], row["Accuracy %"]),
        textcoords="offset points",
        xytext=(6,4), fontsize=8)
axes[1,1].set_xlabel("Test Loss (lower = better)")
axes[1,1].set_ylabel("Test Accuracy (%)")
axes[1,1].set_title("Accuracy vs Loss\n(top-left corner = best)",
                    fontweight='bold')
axes[1,1].legend(handles=[
    mpatches.Patch(color='gold',    label='🥇 Best'),
    mpatches.Patch(color='silver',  label='🥈 2nd'),
    mpatches.Patch(color='#cd7f32', label='🥉 3rd'),
    mpatches.Patch(color='steelblue',label='Others'),
])

plt.tight_layout()
dash_path = '/content/drive/MyDrive/model_dashboard.png'
plt.savefig(dash_path, bbox_inches='tight', dpi=150)
plt.show()

# ── Save CSV ───────────────────────────────────────────────
csv_path = '/content/drive/MyDrive/model_comparison.csv'
df.to_csv(csv_path, index=False)
print(f"\n✅ Dashboard saved → {dash_path}")
print(f"✅ CSV saved       → {csv_path}")

