import os, mlflow

os.environ["MLFLOW_ALLOW_FILE_STORE"] = "true"

# Clean any corrupted mlruns and start fresh
if os.path.exists("/content/mlruns"):
    shutil.rmtree("/content/mlruns")
    print("🗑️ Cleared old mlruns")

mlflow.set_tracking_uri("file:///content/mlruns")
mlflow.set_experiment("Capacitor_Orientation")
print("✅ MLflow", mlflow.__version__, "ready!")

# Log all 5 models
all_runs = [
    {"run_name":"CNN_V1",         "model":"CNN_V1",
     "accuracy":0.7407,"loss":1.3383,"f1":0.7339,
     "b":0.62,"l":0.82,"r":0.67,"t":0.80,
     "epochs":"16","batch":"32","dropout":"None",
     "l2":"None","imgs":"27","aug":"?","split":"original"},

    {"run_name":"CNN_V2",         "model":"CNN_V2",
     "accuracy":0.7407,"loss":1.0568,"f1":0.7264,
     "b":0.62,"l":0.82,"r":0.67,"t":0.80,
     "epochs":"16","batch":"32","dropout":"None",
     "l2":"None","imgs":"27","aug":"?","split":"original"},

    {"run_name":"CNN_V3",         "model":"CNN_V3",
     "accuracy":0.7895,"loss":1.6065,"f1":0.7738,
     "b":0.57,"l":0.83,"r":0.86,"t":0.83,
     "epochs":"21","batch":"16","dropout":"0.25/0.3/0.5",
     "l2":"1e-4","imgs":"2945","aug":"18","split":"80_10_10"},

    {"run_name":"MobileNetV2",    "model":"MobileNetV2",
     "accuracy":0.7368,"loss":1.8689,"f1":0.7102,
     "b":0.57,"l":0.83,"r":0.67,"t":0.77,
     "epochs":"25","batch":"16","dropout":"0.4/0.3",
     "l2":"None","imgs":"2945","aug":"18","split":"80_10_10"},

    {"run_name":"EfficientNetB0", "model":"EfficientNetB0",
     "accuracy":0.7895,"loss":1.2998,"f1":0.7767,
     "b":0.57,"l":0.91,"r":0.86,"t":0.77,
     "epochs":"17","batch":"16","dropout":"0.4/0.3",
     "l2":"None","imgs":"2945","aug":"18","split":"80_10_10"},
]

import matplotlib.pyplot as plt

for r in all_runs:
    # Generate per-run F1 chart
    fig, ax = plt.subplots(figsize=(6, 4))
    classes = ["Bottom","Left","Right","Top"]
    f1s     = [r["b"], r["l"], r["r"], r["t"]]
    bar_colors = ['#e74c3c' if v < 0.70 else
                  '#f39c12' if v < 0.80 else
                  '#2ecc71' for v in f1s]
    bars = ax.bar(classes, [v*100 for v in f1s], color=bar_colors)
    ax.set_ylim(0, 110)
    ax.set_ylabel("F1 Score (%)")
    ax.set_title(f"{r['run_name']} — Per-Class F1")
    ax.axhline(y=80, color='gray', linestyle='--', alpha=0.5, label='80% line')
    for bar, v in zip(bars, f1s):
        ax.text(bar.get_x()+bar.get_width()/2,
                v*100+1, f"{v*100:.0f}%",
                ha='center', fontsize=11, fontweight='bold')
    run_plot = f"/tmp/{r['run_name']}_f1.png"
    plt.savefig(run_plot, bbox_inches='tight', dpi=120)
    plt.close()

    with mlflow.start_run(run_name=r["run_name"]):
        mlflow.log_params({
            "model":        r["model"],
            "img_size":     "224x224",
            "batch_size":   r["batch"],
            "epochs_run":   r["epochs"],
            "dropout":      r["dropout"],
            "l2_reg":       r["l2"],
            "train_images": r["imgs"],
            "aug_variants": r["aug"],
            "split":        r["split"],
        })
        mlflow.log_metrics({
            "test_accuracy": r["accuracy"],
            "test_loss":     r["loss"],
            "macro_f1":      r["f1"],
            "Bottom_f1":     r["b"],
            "Left_f1":       r["l"],
            "Right_f1":      r["r"],
            "Top_f1":        r["t"],
        })
        mlflow.log_artifact(run_plot)
        print(f"✅ {r['run_name']:20s} acc={r['accuracy']:.2%}  f1={r['f1']:.2%}")

# Backup
shutil.copytree("/content/mlruns",
                "/content/drive/MyDrive/mlruns_backup",
                dirs_exist_ok=True)
print("\n✅ All 5 models logged & backed up!")

