# ── Full inline MLflow-style dashboard ────────────────────
import pandas as pd
import matplotlib.pyplot as plt
import matplotlib.patches as mpatches
import numpy as np
from IPython.display import display, HTML
import os, mlflow

os.environ["MLFLOW_ALLOW_FILE_STORE"] = "true"
mlflow.set_tracking_uri("file:///content/mlruns")
client = mlflow.tracking.MlflowClient()

rows = []
for exp in client.search_experiments():
    for run in client.search_runs(experiment_ids=[exp.experiment_id]):
        m = run.data.metrics
        p = run.data.params
        rows.append({
            "Model":        run.info.run_name,
            "Accuracy %":   round(m.get("test_accuracy",0)*100, 2),
            "Macro F1 %":   round(m.get("macro_f1",0)*100, 2),
            "Loss":         round(m.get("test_loss",0), 4),
            "Epochs":       p.get("epochs_run","?"),
            "Train Images": p.get("train_images","?"),
            "Batch Size":   p.get("batch_size","?"),
            "Dropout":      p.get("dropout","None"),
            "L2 Reg":       p.get("l2_reg","None"),
            "Aug":          p.get("aug_variants","?"),
            "Split":        p.get("split","?"),
            "Bottom F1":    round(m.get("Bottom_f1",0)*100,1),
            "Left F1":      round(m.get("Left_f1",0)*100,1),
            "Right F1":     round(m.get("Right_f1",0)*100,1),
            "Top F1":       round(m.get("Top_f1",0)*100,1),
        })

df = pd.DataFrame(rows).sort_values(
    "Accuracy %", ascending=False).reset_index(drop=True)
df.insert(0, "Rank", ["1st","2nd","3rd","4th","5th"][:len(df)])

# ── Colour-coded HTML table ────────────────────────────────
def color_val(val):
    try:
        v = float(val)
        if v >= 78: return 'background-color:#2ecc71;color:white'
        elif v >= 73: return 'background-color:#f39c12;color:white'
        else: return 'background-color:#e74c3c;color:white'
    except: return ''

styled = df.style\
    .map(color_val, subset=["Accuracy %","Macro F1 %",
                             "Bottom F1","Left F1",
                             "Right F1","Top F1"])\
    .set_properties(**{
        'text-align':'center',
        'font-size':'13px',
        'border':'1px solid #ddd',
        'padding':'8px'
    })\
    .set_table_styles([{
        'selector':'th',
        'props':[('background-color','#2c3e50'),
                 ('color','white'),
                 ('font-size','14px'),
                 ('text-align','center'),
                 ('padding','10px')]
    },{
        'selector':'caption',
        'props':[('font-size','18px'),
                 ('font-weight','bold'),
                 ('padding','10px')]
    }])\
    .set_caption("Model Comparison — Capacitor Orientation")

display(styled)

best = df.iloc[0]
print(f"\nBEST MODEL : {best['Model']}")
print(f"Accuracy   : {best['Accuracy %']}%")
print(f"Macro F1   : {best['Macro F1 %']}%")
print(f"Loss       : {best['Loss']}")

# ── Dashboard plots ────────────────────────────────────────
models = df["Model"].tolist()
colors = ['#f1c40f','#bdc3c7','#cd7f32','#3498db','#9b59b6'][:len(models)]

fig, axes = plt.subplots(2, 2, figsize=(18, 12))
fig.suptitle('Model Comparison Dashboard — Capacitor Orientation',
             fontsize=16, fontweight='bold', y=1.01)

# 1. Accuracy
axes[0,0].barh(models, df["Accuracy %"], color=colors, edgecolor='black')
axes[0,0].set_xlim(0, 110)
axes[0,0].set_title("Test Accuracy (%)", fontweight='bold', fontsize=13)
axes[0,0].axvline(x=75, color='red', linestyle='--', alpha=0.5, label='75% baseline')
axes[0,0].legend()
for i, v in enumerate(df["Accuracy %"]):
    axes[0,0].text(v+0.5, i, f"{v}%", va='center', fontsize=10)

# 2. Macro F1
axes[0,1].barh(models, df["Macro F1 %"], color=colors, edgecolor='black')
axes[0,1].set_xlim(0, 110)
axes[0,1].set_title("Macro F1 Score (%)", fontweight='bold', fontsize=13)
axes[0,1].axvline(x=75, color='red', linestyle='--', alpha=0.5)
for i, v in enumerate(df["Macro F1 %"]):
    axes[0,1].text(v+0.5, i, f"{v}%", va='center', fontsize=10)

# 3. Per-class F1
x = np.arange(len(models))
w = 0.2
cls_data   = ["Bottom F1","Left F1","Right F1","Top F1"]
cls_colors = ['#e74c3c','#3498db','#2ecc71','#f39c12']
for i,(cls,col) in enumerate(zip(cls_data, cls_colors)):
    bars = axes[1,0].bar(x+i*w, df[cls], w,
                         label=cls.replace(" F1",""), color=col)
axes[1,0].set_xticks(x+w*1.5)
axes[1,0].set_xticklabels(models, rotation=20, ha='right', fontsize=9)
axes[1,0].set_title("Per-Class F1 (%)", fontweight='bold', fontsize=13)
axes[1,0].set_ylim(0, 115)
axes[1,0].axhline(y=80, color='gray', linestyle='--', alpha=0.5)
axes[1,0].legend()

# 4. Accuracy vs Loss
axes[1,1].scatter(df["Loss"], df["Accuracy %"],
                  c=colors, s=300, zorder=5, edgecolors='black')
for _, row in df.iterrows():
    axes[1,1].annotate(row["Model"],
        (row["Loss"], row["Accuracy %"]),
        textcoords="offset points", xytext=(6,4), fontsize=9)
axes[1,1].set_xlabel("Test Loss (lower=better)", fontsize=11)
axes[1,1].set_ylabel("Test Accuracy (%)", fontsize=11)
axes[1,1].set_title("Accuracy vs Loss\n(top-left = best)",
                    fontweight='bold', fontsize=13)

plt.tight_layout()
plt.savefig('/content/drive/MyDrive/model_dashboard.png',
            bbox_inches='tight', dpi=150)
plt.show()
print("Dashboard saved to Drive!")

import pandas as pd
