from IPython.display import display, HTML
import os, mlflow

os.environ["MLFLOW_ALLOW_FILE_STORE"] = "true"
mlflow.set_tracking_uri("file:///content/mlruns")
client = mlflow.tracking.MlflowClient()

# ── Collect runs ───────────────────────────────────────────
rows = []
for exp in client.search_experiments():
    for run in client.search_runs(experiment_ids=[exp.experiment_id]):
        m = run.data.metrics
        p = run.data.params
        rows.append({
            "Model":        run.info.run_name,
            "Accuracy %":   round(m.get("test_accuracy",0)*100, 2),
            "Macro F1 %":   round(m.get("macro_f1",0)*100, 2),
            "Loss":         round(m.get("test_loss",0), 4),
            "Epochs":       p.get("epochs_run","?"),
            "Train Images": p.get("train_images","?"),
            "Batch":        p.get("batch_size","?"),
            "Dropout":      p.get("dropout","None"),
            "L2":           p.get("l2_reg","None"),
            "Aug":          p.get("aug_variants","?"),
            "Split":        p.get("split","?"),
            "Bottom F1":    round(m.get("Bottom_f1",0)*100, 1),
            "Left F1":      round(m.get("Left_f1",0)*100, 1),
            "Right F1":     round(m.get("Right_f1",0)*100, 1),
            "Top F1":       round(m.get("Top_f1",0)*100, 1),
        })

df = pd.DataFrame(rows).sort_values(
    "Accuracy %", ascending=False).reset_index(drop=True)

# ── HTML Dashboard ─────────────────────────────────────────
def make_cell(val, is_metric=False):
    try:
        v = float(val)
        if is_metric:
            if v >= 78:   bg = "#27ae60"
            elif v >= 73: bg = "#f39c12"
            else:         bg = "#e74c3c"
            return f'<td style="background:{bg};color:white;font-weight:bold;text-align:center;padding:8px">{val}</td>'
    except: pass
    return f'<td style="text-align:center;padding:8px">{val}</td>'

medal = ["🥇","🥈","🥉","4th","5th"]

html = """
<style>
  table {border-collapse:collapse; width:100%; font-family:Arial; font-size:13px}
  th {background:#2c3e50; color:white; padding:10px; text-align:center}
  tr:nth-child(even) {background:#f8f9fa}
  tr:hover {background:#e8f4fd}
  .title {font-size:20px; font-weight:bold; text-align:center;
          padding:15px; background:#2c3e50; color:white; margin-bottom:5px}
  .section {font-size:15px; font-weight:bold; background:#34495e;
            color:white; padding:8px; text-align:center}
</style>

<div class="title">🏆 Model Comparison Dashboard — Capacitor Orientation</div>

<table>
<tr>
  <th>Rank</th><th>Model</th>
  <th>Accuracy %</th><th>Macro F1 %</th><th>Loss</th>
  <th>Epochs</th><th>Train Images</th><th>Batch</th>
  <th>Dropout</th><th>L2</th><th>Aug</th><th>Split</th>
</tr>
"""

for i, row in df.iterrows():
    html += "<tr>"
    html += f'<td style="text-align:center;font-weight:bold;padding:8px">{medal[i]}</td>'
    html += f'<td style="text-align:center;font-weight:bold;padding:8px">{row["Model"]}</td>'
    html += make_cell(row["Accuracy %"], True)
    html += make_cell(row["Macro F1 %"], True)
    html += make_cell(row["Loss"])
    html += make_cell(row["Epochs"])
    html += make_cell(row["Train Images"])
    html += make_cell(row["Batch"])
    html += make_cell(row["Dropout"])
    html += make_cell(row["L2"])
    html += make_cell(row["Aug"])
    html += make_cell(row["Split"])
    html += "</tr>"

html += "</table><br>"

# Per-class F1 table
html += '<div class="section">📊 Per-Class F1 Scores (%)</div>'
html += "<table><tr><th>Rank</th><th>Model</th><th>Bottom F1</th><th>Left F1</th><th>Right F1</th><th>Top F1</th></tr>"
for i, row in df.iterrows():
    html += "<tr>"
    html += f'<td style="text-align:center;font-weight:bold;padding:8px">{medal[i]}</td>'
    html += f'<td style="text-align:center;font-weight:bold;padding:8px">{row["Model"]}</td>'
    html += make_cell(row["Bottom F1"], True)
    html += make_cell(row["Left F1"],   True)
    html += make_cell(row["Right F1"],  True)
    html += make_cell(row["Top F1"],    True)
    html += "</tr>"
html += "</table><br>"

# Best model box
best = df.iloc[0]
html += f"""
<div style="background:#27ae60;color:white;padding:15px;
            border-radius:8px;text-align:center;font-size:15px">
  <b>🥇 BEST MODEL: {best['Model']}</b><br>
  Accuracy: {best['Accuracy %']}% &nbsp;|&nbsp;
  Macro F1: {best['Macro F1 %']}% &nbsp;|&nbsp;
  Loss: {best['Loss']} &nbsp;|&nbsp;
  Epochs: {best['Epochs']} &nbsp;|&nbsp;
  Train Images: {best['Train Images']}
</div>
"""

display(HTML(html))

# ── Visual Charts ──────────────────────────────────────────
