bars = ax.barh(models, df["Accuracy"], color=colors, edgecolor='black')
ax.set_xlim(0, 110)
ax.set_title("Test Accuracy (%)", fontweight='bold', fontsize=14)
ax.axvline(x=75, color='red', linestyle='--', alpha=0.5, label='75%')
ax.legend()
for i, v in enumerate(df["Accuracy"]):
    ax.text(v+0.5, i, f"{v}%", va='center', fontsize=11)
plt.tight_layout()
chart1 = fig_to_base64(fig); plt.close()

# Chart 2 — Macro F1
