def color_cell(v, is_pct=True):
    try:
        fv = float(v)
        if is_pct:
            if fv >= 78:   c = "#27ae60"
            elif fv >= 73: c = "#f39c12"
            else:          c = "#e74c3c"
            return f'style="background:{c};color:white;font-weight:bold"'
    except: pass
    return ""

