# ============================================================
# CELL 1 — Mount Drive
# ============================================================
from google.colab import drive
drive.mount('/content/drive')

import os
print(os.listdir("/content/drive/MyDrive"))

# ============================================================
# CELL 2 — Imports & Config
# ============================================================
import tensorflow as tf
from tensorflow.keras import layers, models
import numpy as np
import matplotlib.pyplot as plt
from sklearn.metrics import classification_report, confusion_matrix
import seaborn as sns

IMG_SIZE    = (224, 224)
BATCH_SIZE  = 16
DATASET_PATH = "/content/drive/MyDrive/PCB_AI_Split_Dataset"
CLASS_NAMES  = ["Bottom", "Left", "Right", "Top"]

print("TF version:", tf.__version__)

# ============================================================
# CELL 3 — Define Augmentation Pipeline
# ============================================================
# Same augmentation pipeline you settled on previously
data_augmentation = tf.keras.Sequential([
    layers.RandomContrast(0.05),
    layers.RandomTranslation(height_factor=0.03, width_factor=0.03),
    layers.Lambda(lambda x: tf.image.random_brightness(x, max_delta=0.15)),
    layers.Lambda(lambda x: tf.image.random_saturation(x, lower=0.8, upper=1.2)),
    layers.Lambda(lambda x: tf.image.random_hue(x, max_delta=0.08)),
], name="augmentation")

# ============================================================
# CELL 4 — Load Raw Datasets (no augmentation yet)
# ============================================================
train_ds_raw = tf.keras.preprocessing.image_dataset_from_directory(
    f"{DATASET_PATH}/train",
    image_size=IMG_SIZE,
    batch_size=BATCH_SIZE,
    shuffle=True,
    seed=42,
    label_mode="int"
)

valid_ds_raw = tf.keras.preprocessing.image_dataset_from_directory(
    f"{DATASET_PATH}/valid",
    image_size=IMG_SIZE,
    batch_size=BATCH_SIZE,
    shuffle=False,
    label_mode="int"
)

test_ds_raw = tf.keras.preprocessing.image_dataset_from_directory(
    f"{DATASET_PATH}/test",
    image_size=IMG_SIZE,
    batch_size=BATCH_SIZE,
    shuffle=False,   # KEEP FALSE — needed for correct label alignment during eval
    label_mode="int"
)

print("Class names:", train_ds_raw.class_names)

# ============================================================
# CELL 5 — Apply Augmentation to ALL THREE Splits
# NOTE: training=True forces augmentation to run at inference time too.
#       This simulates "test-time augmentation" (TTA).
# ============================================================

def augment(images, labels):
    images = data_augmentation(images, training=True)
    return images, labels

def rescale(images, labels):
    # EfficientNet expects [0,255] inputs — it has its own internal rescaling
    # So just cast to float32 here; do NOT divide by 255
    return tf.cast(images, tf.float32), labels

AUTOTUNE = tf.data.AUTOTUNE

train_ds = (
    train_ds_raw
    .map(augment,  num_parallel_calls=AUTOTUNE)
    .map(rescale,  num_parallel_calls=AUTOTUNE)
    .prefetch(AUTOTUNE)
)

valid_ds = (
    valid_ds_raw
    .map(augment,  num_parallel_calls=AUTOTUNE)
    .map(rescale,  num_parallel_calls=AUTOTUNE)
    .prefetch(AUTOTUNE)
)

test_ds = (
    test_ds_raw
    .map(augment,  num_parallel_calls=AUTOTUNE)
    .map(rescale,  num_parallel_calls=AUTOTUNE)
    .prefetch(AUTOTUNE)
)

print("✅ All 3 splits loaded & augmented")

# ============================================================
# CELL 6 — Quick sanity check: visualise augmented test samples
# ============================================================
for images, labels in test_ds.take(1):
    plt.figure(figsize=(12, 6))
    for i in range(8):
        ax = plt.subplot(2, 4, i + 1)
        plt.imshow(images[i].numpy().astype("uint8"))
        plt.title(CLASS_NAMES[labels[i].numpy()])
        plt.axis("off")
    plt.suptitle("Augmented TEST samples (sanity check)", fontsize=13)
    plt.tight_layout()
    plt.show()

# ============================================================
# CELL 7 — Build EfficientNetB0 Model
# ============================================================
base_model = tf.keras.applications.EfficientNetB0(
    include_top=False,
    weights="imagenet",
    input_shape=(224, 224, 3)
)
base_model.trainable = False   # freeze backbone first

inputs  = tf.keras.Input(shape=(224, 224, 3))
x       = base_model(inputs, training=False)
x       = layers.GlobalAveragePooling2D()(x)
x       = layers.Dropout(0.4)(x)
outputs = layers.Dense(4, activation="softmax")(x)

model = tf.keras.Model(inputs, outputs, name="EfficientNetB0_FullAug")

model.compile(
    optimizer=tf.keras.optimizers.Adam(1e-3),
    loss="sparse_categorical_crossentropy",
    metrics=["accuracy"]
)

model.summary()

# ============================================================
# CELL 8 — Callbacks
# ============================================================
SAVE_PATH = "/content/drive/MyDrive/efficientnetb0_fullaug.keras"

callbacks = [
    tf.keras.callbacks.ModelCheckpoint(
        SAVE_PATH,
        monitor="val_accuracy",
        save_best_only=True,
        verbose=1
    ),
    tf.keras.callbacks.EarlyStopping(
        monitor="val_accuracy",
        patience=5,
        restore_best_weights=True,
        verbose=1
    ),
    tf.keras.callbacks.ReduceLROnPlateau(
        monitor="val_loss",
        factor=0.5,
        patience=3,
        verbose=1
    )
]

# ============================================================
# CELL 9 — Phase 1: Train with frozen backbone
# ============================================================
print("=== Phase 1: Frozen backbone ===")
history_phase1 = model.fit(
    train_ds,
    validation_data=valid_ds,
    epochs=17,          # same as your best EfficientNetB0 run
    callbacks=callbacks
)

# ============================================================
# CELL 10 — Phase 2: Fine-tune top layers (optional, unfreeze last 20)
# ============================================================
print("=== Phase 2: Fine-tuning top 20 layers ===")
base_model.trainable = True
for layer in base_model.layers[:-20]:
    layer.trainable = False

model.compile(
    optimizer=tf.keras.optimizers.Adam(1e-4),   # lower LR for fine-tune
    loss="sparse_categorical_crossentropy",
    metrics=["accuracy"]
)

history_phase2 = model.fit(
    train_ds,
    validation_data=valid_ds,
    epochs=10,
    callbacks=callbacks
)

# ============================================================
# CELL 11 — Evaluate on AUGMENTED test set
# ============================================================
print("\n=== Evaluation on AUGMENTED test set ===")
test_loss, test_acc = model.evaluate(test_ds, verbose=1)
print(f"Test Accuracy : {test_acc*100:.2f}%")
print(f"Test Loss     : {test_loss:.4f}")

# ============================================================
# CELL 12 — Classification Report & Confusion Matrix
# ============================================================
y_true, y_pred = [], []

for images, labels in test_ds:
    preds = model.predict(images, verbose=0)
    y_pred.extend(np.argmax(preds, axis=1))
    y_true.extend(labels.numpy())

print("\n=== Classification Report ===")
print(classification_report(y_true, y_pred, target_names=CLASS_NAMES))

cm = confusion_matrix(y_true, y_pred)
plt.figure(figsize=(7, 6))
sns.heatmap(cm, annot=True, fmt="d", cmap="Blues",
            xticklabels=CLASS_NAMES, yticklabels=CLASS_NAMES)
plt.title("Confusion Matrix — EfficientNetB0 (Full Augmentation)")
plt.ylabel("True Label")
plt.xlabel("Predicted Label")
plt.tight_layout()
plt.savefig("/content/drive/MyDrive/cm_efficientnetb0_fullaug.png", dpi=150)
plt.show()

# ============================================================
# CELL 13 — Compare vs original (no-aug test) baseline
# ============================================================
# Original EfficientNetB0: Acc=78.95%, Macro F1=77.67%
print("\n=== Comparison ===")
print(f"{'Metric':<20} {'Original':>10} {'Full Aug':>10}")
print("-" * 42)
print(f"{'Accuracy':<20} {'78.95%':>10} {test_acc*100:>9.2f}%")

# Macro F1 from report
from sklearn.metrics import f1_score
macro_f1 = f1_score(y_true, y_pred, average="macro") * 100
print(f"{'Macro F1':<20} {'77.67%':>10} {macro_f1:>9.2f}%")
print(f"{'Loss':<20} {'1.2998':>10} {test_loss:>10.4f}")

