model = tf.keras.Model(inputs, outputs, name="EfficientNetB0_Clean")

model.compile(
    optimizer=tf.keras.optimizers.Adam(1e-3),
    loss="sparse_categorical_crossentropy",
    metrics=["accuracy"]
)
model.summary()

# CELL 5 — Callbacks
SAVE_PATH = "/content/drive/MyDrive/efficientnetb0_v2_clean.keras"

callbacks = [
    tf.keras.callbacks.ModelCheckpoint(
        SAVE_PATH,
        monitor="val_accuracy",
        save_best_only=True,
        verbose=1
    ),
    tf.keras.callbacks.EarlyStopping(
        monitor="val_accuracy",
        patience=5,
        restore_best_weights=True,
        verbose=1
    ),
    tf.keras.callbacks.ReduceLROnPlateau(
        monitor="val_loss",
        factor=0.5,
        patience=3,
        verbose=1
    )
]

# CELL 6 — Phase 1: Train frozen backbone
print("=== Phase 1: Frozen backbone ===")
history = model.fit(
    train_ds,
    validation_data=valid_ds,
    epochs=20,
    callbacks=callbacks
)

# CELL 7 — Phase 2: Fine-tune top layers
print("=== Phase 2: Fine-tune last 20 layers ===")
base_model.trainable = True
for layer in base_model.layers[:-20]:
    layer.trainable = False

model.compile(
    optimizer=tf.keras.optimizers.Adam(1e-5),  # much lower LR
    loss="sparse_categorical_crossentropy",
    metrics=["accuracy"]
)

history_ft = model.fit(
    train_ds,
    validation_data=valid_ds,
    epochs=15,
    callbacks=callbacks
)

# CELL 8 — Evaluate on clean test set
import numpy as np
from sklearn.metrics import classification_report, confusion_matrix
import seaborn as sns
import matplotlib.pyplot as plt

print("\n=== Evaluation on CLEAN test set ===")
test_loss, test_acc = model.evaluate(test_ds, verbose=1)
print(f"Test Accuracy : {test_acc*100:.2f}%")
print(f"Test Loss     : {test_loss:.4f}")

y_true, y_pred = [], []
for images, labels in test_ds:
    preds = model.predict(images, verbose=0)
    y_pred.extend(np.argmax(preds, axis=1))
    y_true.extend(labels.numpy())

print("\n=== Classification Report ===")
print(classification_report(y_true, y_pred, target_names=CLASS_NAMES))

cm = confusion_matrix(y_true, y_pred)
plt.figure(figsize=(7, 6))
sns.heatmap(cm, annot=True, fmt="d", cmap="Blues",
            xticklabels=CLASS_NAMES, yticklabels=CLASS_NAMES)
plt.title("Confusion Matrix — EfficientNetB0 v2 (Fine-tuned)")
plt.ylabel("True Label")
plt.xlabel("Predicted Label")
plt.tight_layout()
plt.savefig("/content/drive/MyDrive/cm_efficientnetb0_v2.png", dpi=150)
plt.show()

# CELL 9 — Comparison
from sklearn.metrics import f1_score
macro_f1 = f1_score(y_true, y_pred, average="macro") * 100
print(f"\n=== Comparison vs Best Previous Run ===")
print(f"{'Metric':<20} {'Original':>10} {'This Run':>10}")
print("-" * 42)
print(f"{'Accuracy':<20} {'78.95%':>10} {test_acc*100:>9.2f}%")
print(f"{'Macro F1':<20} {'77.67%':>10} {macro_f1:>9.2f}%")
print(f"{'Loss':<20} {'1.2998':>10} {test_loss:>10.4f}")

# ============================================================
# Dataset Image Count — Before & After Augmentation
# ============================================================
import os
from collections import defaultdict

CLASS_NAMES = ["Bottom", "Left", "Right", "Top"]

def count_images(split_path, label=""):
    print(f"\n{'='*50}")
    print(f"  {label} — {split_path}")
    print(f"{'='*50}")

    total = 0
    counts = {}

    for cls in CLASS_NAMES:
        cls_path = os.path.join(split_path, cls)
        if os.path.exists(cls_path):
            n = len([
                f for f in os.listdir(cls_path)
                if f.lower().endswith(('.jpg', '.jpeg', '.png'))
            ])
            counts[cls] = n
            total += n
            print(f"  {cls:<10}: {n:>4} images")
        else:
            print(f"  {cls:<10}: folder NOT FOUND")

    print(f"  {'TOTAL':<10}: {total:>4} images")
    return counts, total

# ── Roboflow downloaded dataset (what we're currently using) ──
ROBOFLOW_PATH = DATASET_PATH   # from dataset.location

print("\n" + "🔵 "*20)
print("  ROBOFLOW DATASET (after augmentation by Roboflow)")
print("🔵 "*20)

rf_train, rf_train_total = count_images(f"{ROBOFLOW_PATH}/train", "TRAIN (augmented)")
rf_valid, rf_valid_total = count_images(f"{ROBOFLOW_PATH}/valid", "VALID")
rf_test,  rf_test_total  = count_images(f"{ROBOFLOW_PATH}/test",  "TEST")

rf_total = rf_train_total + rf_valid_total + rf_test_total

# ── Original dataset (before augmentation) ──
# Roboflow version(1) is typically the raw original
# Approximate: train original = train_aug / 18 (your aug multiplier)
print("\n" + "🟡 "*20)
print("  ESTIMATED ORIGINAL (before Roboflow augmentation)")
print("🟡 "*20)

AUG_MULTIPLIER = 18   # your Roboflow augmentation setting

print(f"\n  Augmentation multiplier used: {AUG_MULTIPLIER}x")
print(f"\n  TRAIN split:")
for cls in CLASS_NAMES:
    if cls in rf_train:
        orig = round(rf_train[cls] / AUG_MULTIPLIER)
        print(f"    {cls:<10}: ~{orig:>3} original  →  {rf_train[cls]:>4} after aug ({AUG_MULTIPLIER}x)")

print(f"\n  VALID split (not augmented by Roboflow):")
for cls in CLASS_NAMES:
    if cls in rf_valid:
        print(f"    {cls:<10}: {rf_valid[cls]:>4} images")

print(f"\n  TEST split (not augmented by Roboflow):")
for cls in CLASS_NAMES:
    if cls in rf_test:
        print(f"    {cls:<10}: {rf_test[cls]:>4} images")

# ── Summary Table ──
print("\n" + "="*55)
print("  SUMMARY TABLE")
print("="*55)
print(f"  {'Split':<10} {'Before Aug':>12} {'After Aug':>12}")
print(f"  {'-'*36}")

orig_train = round(rf_train_total / AUG_MULTIPLIER)
print(f"  {'Train':<10} {orig_train:>12} {rf_train_total:>12}")
print(f"  {'Valid':<10} {rf_valid_total:>12} {rf_valid_total:>12}  (unchanged)")
print(f"  {'Test':<10} {rf_test_total:>12} {rf_test_total:>12}  (unchanged)")
print(f"  {'-'*36}")
orig_total = orig_train + rf_valid_total + rf_test_total
print(f"  {'TOTAL':<10} {orig_total:>12} {rf_total:>12}")
print("="*55)

