import pandas as pd
import matplotlib.pyplot as plt
import numpy as np
from IPython.display import display, HTML
import os, mlflow

os.environ["MLFLOW_ALLOW_FILE_STORE"] = "true"
mlflow.set_tracking_uri("file:///content/mlruns")
client = mlflow.tracking.MlflowClient()

# ── Collect ONLY V3_Clean runs ─────────────────────────────
rows = []
for exp in client.search_experiments():
    for run in client.search_runs(
        experiment_ids=[exp.experiment_id],
        filter_string="params.data_version = 'V3_Clean'"  # ✅ only new runs
    ):
        m = run.data.metrics
        p = run.data.params

        # ✅ Use logged model_name param, fallback to run name
        model_display = p.get("model_name", run.info.run_name)

        rows.append({
            "Model":        model_display,
            "Accuracy %":   round(m.get("test_accuracy", 0) * 100, 2),
            "Macro F1 %":   round(m.get("macro_f1",      0) * 100, 2),
            "Loss":         round(m.get("test_loss",      0), 4),
            "Epochs":       p.get("epochs_run",    "?"),   # ✅ best epoch
            "Train Images": p.get("train_images",  "?"),   # ✅ shows 2641
            "Batch":        p.get("batch_size",    "?"),
            "Dropout":      p.get("dropout",       "None"),
            "L2":           p.get("l2_reg",        "None"),
            "Aug":          p.get("aug_variants",  "?"),
            "Split":        p.get("split",         "?"),
            "Bottom F1":    round(m.get("Bottom_f1", 0) * 100, 1),
            "Left F1":      round(m.get("Left_f1",   0) * 100, 1),
            "Right F1":     round(m.get("Right_f1",  0) * 100, 1),
            "Top F1":       round(m.get("Top_f1",    0) * 100, 1),
        })

# ✅ Safety check
if not rows:
    print("⚠️ No V3_Clean runs found!")
    print("Make sure you've added  mlflow.log_param('data_version', 'V3_Clean')")
    print("to your training code and re-run at least one model.")
else:
    df = pd.DataFrame(rows).sort_values(
        "Accuracy %", ascending=False).reset_index(drop=True)

    print(f"✅ Found {len(df)} V3_Clean run(s): {df['Model'].tolist()}")

    # ── HTML Dashboard ─────────────────────────────────────
    def make_cell(val, is_metric=False):
        try:
            v = float(val)
            if is_metric:
                if v >= 78:   bg = "#27ae60"
                elif v >= 73: bg = "#f39c12"
                else:         bg = "#e74c3c"
                return f'<td style="background:{bg};color:white;font-weight:bold;text-align:center;padding:8px">{val}</td>'
        except: pass
        return f'<td style="text-align:center;padding:8px">{val}</td>'

    medals = ["🥇","🥈","🥉","4th","5th","6th","7th","8th"]

    html = """
    <style>
      table {border-collapse:collapse; width:100%; font-family:Arial; font-size:13px}
      th {background:#2c3e50; color:white; padding:10px; text-align:center}
      tr:nth-child(even) {background:#f8f9fa}
      tr:hover {background:#e8f4fd}
      .title {font-size:20px; font-weight:bold; text-align:center;
              padding:15px; background:#2c3e50; color:white; margin-bottom:5px}
      .section {font-size:15px; font-weight:bold; background:#34495e;
                color:white; padding:8px; text-align:center}
    </style>
    <div class="title">🏆 Model Comparison Dashboard — Capacitor Orientation (V3 Clean Dataset)</div>
    <table>
    <tr>
      <th>Rank</th><th>Model</th>
      <th>Accuracy %</th><th>Macro F1 %</th><th>Loss</th>
      <th>Epochs</th><th>Train Images</th><th>Batch</th>
      <th>Dropout</th><th>L2</th><th>Aug</th><th>Split</th>
    </tr>
    """

    for i, row in df.iterrows():
        medal = medals[i] if i < len(medals) else str(i+1)
        html += "<tr>"
        html += f'<td style="text-align:center;font-weight:bold;padding:8px">{medal}</td>'
        html += f'<td style="text-align:center;font-weight:bold;padding:8px">{row["Model"]}</td>'
        html += make_cell(row["Accuracy %"], True)
        html += make_cell(row["Macro F1 %"], True)
        html += make_cell(row["Loss"])
        html += make_cell(row["Epochs"])
        html += make_cell(row["Train Images"])
        html += make_cell(row["Batch"])
        html += make_cell(row["Dropout"])
        html += make_cell(row["L2"])
        html += make_cell(row["Aug"])
        html += make_cell(row["Split"])
        html += "</tr>"

    html += "</table><br>"

    # Per-class F1 table
    html += '<div class="section">📊 Per-Class F1 Scores (%)</div>'
    html += "<table><tr><th>Rank</th><th>Model</th><th>Bottom F1</th><th>Left F1</th><th>Right F1</th><th>Top F1</th></tr>"
    for i, row in df.iterrows():
        medal = medals[i] if i < len(medals) else str(i+1)
        html += "<tr>"
        html += f'<td style="text-align:center;font-weight:bold;padding:8px">{medal}</td>'
        html += f'<td style="text-align:center;font-weight:bold;padding:8px">{row["Model"]}</td>'
        html += make_cell(row["Bottom F1"], True)
        html += make_cell(row["Left F1"],   True)
        html += make_cell(row["Right F1"],  True)
        html += make_cell(row["Top F1"],    True)
        html += "</tr>"
    html += "</table><br>"

    # Best model box
    best = df.iloc[0]
    html += f"""
    <div style="background:#27ae60;color:white;padding:15px;
                border-radius:8px;text-align:center;font-size:15px">
      <b>🥇 BEST MODEL: {best['Model']}</b><br>
      Accuracy: {best['Accuracy %']}% &nbsp;|&nbsp;
      Macro F1: {best['Macro F1 %']}% &nbsp;|&nbsp;
      Loss: {best['Loss']} &nbsp;|&nbsp;
      Epochs: {best['Epochs']} &nbsp;|&nbsp;
      Train Images: {best['Train Images']}
    </div>
    """

    display(HTML(html))

    # ── Charts (only if 2+ models) ──────────────────────────
    if len(df) < 2:
        print("\n⏳ Train more models to see comparison charts!")
    else:
        models  = df["Model"].tolist()
        palette = ['#f1c40f','#bdc3c7','#cd7f32','#3498db',
                   '#9b59b6','#e74c3c','#1abc9c','#e67e22']
        colors  = palette[:len(models)]

        fig, axes = plt.subplots(2, 2, figsize=(18, 12))
        fig.suptitle('Model Comparison — Capacitor Orientation (V3 Clean)',
                     fontsize=16, fontweight='bold')

        # 1. Accuracy
        axes[0,0].barh(models, df["Accuracy %"], color=colors, edgecolor='black')
        axes[0,0].set_xlim(0, 110)
        axes[0,0].set_title("Test Accuracy (%)", fontweight='bold')
        axes[0,0].axvline(x=75, color='red', linestyle='--', alpha=0.5, label='75% baseline')
        axes[0,0].legend(fontsize=9)
        for i, v in enumerate(df["Accuracy %"]):
            axes[0,0].text(v+0.5, i, f"{v}%", va='center', fontsize=10)

        # 2. Macro F1
        axes[0,1].barh(models, df["Macro F1 %"], color=colors, edgecolor='black')
        axes[0,1].set_xlim(0, 110)
        axes[0,1].set_title("Macro F1 Score (%)", fontweight='bold')
        axes[0,1].axvline(x=75, color='red', linestyle='--', alpha=0.5)
        for i, v in enumerate(df["Macro F1 %"]):
            axes[0,1].text(v+0.5, i, f"{v}%", va='center', fontsize=10)

        # 3. Per-class F1
        x = np.arange(len(models))
        w = 0.2
        for j, (cls, col) in enumerate(zip(
                ["Bottom F1","Left F1","Right F1","Top F1"],
                ['#e74c3c','#3498db','#2ecc71','#f39c12'])):
            bars = axes[1,0].bar(x + j*w, df[cls], w,
                                 label=cls.replace(" F1",""), color=col)
            for bar in bars:
                h = bar.get_height()
                axes[1,0].text(bar.get_x() + bar.get_width()/2,
                               h+1, f"{h:.0f}", ha='center', fontsize=7)
        axes[1,0].set_xticks(x + w*1.5)
        axes[1,0].set_xticklabels(models, rotation=20, ha='right', fontsize=9)
        axes[1,0].set_title("Per-Class F1 (%)", fontweight='bold')
        axes[1,0].set_ylim(0, 115)
        axes[1,0].axhline(y=80, color='gray', linestyle='--', alpha=0.5)
        axes[1,0].legend()

        # 4. Accuracy vs Loss
        axes[1,1].scatter(df["Loss"], df["Accuracy %"],
                          c=colors, s=300, zorder=5, edgecolors='black')
        for _, row in df.iterrows():
            axes[1,1].annotate(row["Model"],
                (row["Loss"], row["Accuracy %"]),
                textcoords="offset points", xytext=(6,4), fontsize=9)
        axes[1,1].set_xlabel("Test Loss (lower=better)")
        axes[1,1].set_ylabel("Test Accuracy (%)")
        axes[1,1].set_title("Accuracy vs Loss\n(top-left = best)", fontweight='bold')

        plt.tight_layout()
        plt.savefig('/content/drive/MyDrive/model_dashboard_v3.png',
                    bbox_inches='tight', dpi=150)
        plt.show()
        print("✅ Dashboard saved to Drive!")

