import mlflow
import os

# ✅ Save mlruns TO Drive so it persists between sessions
MLFLOW_PATH = "/content/drive/MyDrive/mlruns"
os.makedirs(MLFLOW_PATH, exist_ok=True)

mlflow.set_tracking_uri(f"file://{MLFLOW_PATH}")
