def make_cell(val, is_metric=False):
    try:
        v = float(val)
        if is_metric:
            if v >= 78:   bg = "#27ae60"
            elif v >= 73: bg = "#f39c12"
            else:         bg = "#e74c3c"
            return f'<td style="background:{bg};color:white;font-weight:bold;text-align:center;padding:8px">{val}</td>'
    except:
        pass
    return f'<td style="text-align:center;padding:8px">{val}</td>'

