import os, shutil, random
import tensorflow as tf
import numpy as np
from sklearn.utils.class_weight import compute_class_weight
from roboflow import Roboflow

# ── Download raw originals ──────────────────────────────────
rf      = Roboflow(api_key="1dxHZ5O6GBW0ZFF237AN")
project = rf.workspace("adityas-workspace-jedzs").project("capacitor-marker-position-projec")
version = project.version(4)
dataset = version.download("folder")

SRC_PATH    = dataset.location
SPLIT_PATH  = "/content/split_v3"
CLASS_NAMES = ["Bottom", "Left", "Right", "Top"]
SEED        = 42
random.seed(SEED)

# ── Split 80/10/10 only if not already done ────────────────
if not os.path.exists(f"{SPLIT_PATH}/train"):
    print("Splitting dataset...")
    for split in ["train", "valid", "test"]:
        for cls in CLASS_NAMES:
            os.makedirs(f"{SPLIT_PATH}/{split}/{cls}", exist_ok=True)

    for cls in CLASS_NAMES:
        imgs = [f for f in os.listdir(f"{SRC_PATH}/{cls}")
                if f.lower().endswith(('.jpg','.jpeg','.png'))]
        random.shuffle(imgs)
        n       = len(imgs)
        n_train = int(n * 0.80)
        n_valid = int(n * 0.10)

        for f in imgs[:n_train]:
            shutil.copy(f"{SRC_PATH}/{cls}/{f}", f"{SPLIT_PATH}/train/{cls}/{f}")
        for f in imgs[n_train:n_train+n_valid]:
            shutil.copy(f"{SRC_PATH}/{cls}/{f}", f"{SPLIT_PATH}/valid/{cls}/{f}")
        for f in imgs[n_train+n_valid:]:
            shutil.copy(f"{SRC_PATH}/{cls}/{f}", f"{SPLIT_PATH}/test/{cls}/{f}")
else:
    print("✅ Split already exists, skipping.")

# ── Verify counts ───────────────────────────────────────────
for split in ["train", "valid", "test"]:
    total = sum(len(os.listdir(f"{SPLIT_PATH}/{split}/{cls}"))
                for cls in CLASS_NAMES)
    per_class = {cls: len(os.listdir(f"{SPLIT_PATH}/{split}/{cls}"))
                 for cls in CLASS_NAMES}
    print(f"{split}: {total} total — {per_class}")

IMG_SIZE   = (224, 224)
BATCH_SIZE = 16
AUTOTUNE   = tf.data.AUTOTUNE

train_ds_raw = tf.keras.preprocessing.image_dataset_from_directory(
    f"{SPLIT_PATH}/train",
    image_size=IMG_SIZE, batch_size=BATCH_SIZE,
    shuffle=True, seed=SEED)

valid_ds_raw = tf.keras.preprocessing.image_dataset_from_directory(
    f"{SPLIT_PATH}/valid",
    image_size=IMG_SIZE, batch_size=BATCH_SIZE, shuffle=False)

test_ds_raw = tf.keras.preprocessing.image_dataset_from_directory(
    f"{SPLIT_PATH}/test",
    image_size=IMG_SIZE, batch_size=BATCH_SIZE, shuffle=False)

CLASS_NAMES = train_ds_raw.class_names
print("Classes:", CLASS_NAMES)

# ── Augmentation (train only) ───────────────────────────────
from tensorflow.keras import layers

augment_layer = tf.keras.Sequential([
    layers.RandomFlip("horizontal_and_vertical"),
    layers.RandomRotation(0.15),
    layers.RandomZoom(0.1),
    layers.RandomContrast(0.1),
    layers.RandomTranslation(height_factor=0.05, width_factor=0.05),
    layers.Lambda(lambda x: tf.image.random_brightness(x, max_delta=0.15)),
    layers.Lambda(lambda x: tf.image.random_saturation(x, lower=0.8, upper=1.2)),
], name="augmentation")

def augment(images, labels):
    return augment_layer(images, training=True), labels

# ── ResNet50V2 needs pixels in [-1, 1] ─────────────────────
def preprocess_resnet(images, labels):
    images = tf.cast(images, tf.float32)
    images = tf.keras.applications.resnet_v2.preprocess_input(images)
    return images, labels

train_ds = (
    train_ds_raw
    .map(augment,           num_parallel_calls=AUTOTUNE)
    .map(preprocess_resnet, num_parallel_calls=AUTOTUNE)
    .prefetch(AUTOTUNE)
)
valid_ds = (
    valid_ds_raw
    .map(preprocess_resnet, num_parallel_calls=AUTOTUNE)
    .prefetch(AUTOTUNE)
)
test_ds = (
    test_ds_raw
    .map(preprocess_resnet, num_parallel_calls=AUTOTUNE)
    .prefetch(AUTOTUNE)
)

# Counts
train_count = sum(1 for _ in train_ds_raw.unbatch())
valid_count = sum(1 for _ in valid_ds_raw.unbatch())
test_count  = sum(1 for _ in test_ds_raw.unbatch())
print(f"Train: {train_count} | Valid: {valid_count} | Test: {test_count}")

# ── Class weights (extra weight on Bottom) ──────────────────
all_labels = []
for _, y in train_ds_raw:
    all_labels.extend(y.numpy())
all_labels = np.array(all_labels)

class_weights = compute_class_weight(
    class_weight="balanced",
    classes=np.unique(all_labels),
    y=all_labels
)
class_weights = dict(enumerate(class_weights))

# ✅ Boost Bottom class extra (index 0) to fix its weak F1
class_weights[0] *= 1.5
print("Class weights (Bottom boosted):", class_weights)

from tensorflow.keras import layers
from tensorflow.keras.callbacks import EarlyStopping, ReduceLROnPlateau, ModelCheckpoint
from sklearn.metrics import confusion_matrix, classification_report
import matplotlib.pyplot as plt
import mlflow

with mlflow.start_run(run_name="ResNet50V2_DataV3_Clean"):

    # ── Build ResNet50V2 ────────────────────────────────────
    base_model = tf.keras.applications.ResNet50V2(
        include_top=False,
        weights="imagenet",
        input_shape=(224, 224, 3)
    )
    base_model.trainable = False

    inputs = tf.keras.Input(shape=(224, 224, 3))
    x      = base_model(inputs, training=False)
    x      = layers.GlobalAveragePooling2D()(x)
    x      = layers.BatchNormalization()(x)
    x      = layers.Dense(256, activation='relu')(x)
    x      = layers.Dropout(0.5)(x)
    x      = layers.Dense(128, activation='relu')(x)
    x      = layers.Dropout(0.3)(x)
    outputs = layers.Dense(4, activation='softmax')(x)

    model = tf.keras.Model(inputs, outputs, name="ResNet50V2")

    model.compile(
        optimizer=tf.keras.optimizers.Adam(1e-3),
        loss='sparse_categorical_crossentropy',
        metrics=['accuracy']
    )
    model.summary()

    callbacks = [
        EarlyStopping(monitor='val_accuracy', patience=7,
                      restore_best_weights=True, verbose=1),
        ReduceLROnPlateau(monitor='val_loss', factor=0.5,
                          patience=3, verbose=1),
        ModelCheckpoint(
            "/content/drive/MyDrive/ResNet50V2_best.keras",
            monitor='val_accuracy', save_best_only=True, verbose=1)
    ]

    # ── Phase 1: Frozen backbone ────────────────────────────
    print("\n=== Phase 1: Frozen backbone (20 epochs) ===")
    history1 = model.fit(
        train_ds,
        validation_data=valid_ds,
        epochs=20,
        class_weight=class_weights,
        callbacks=callbacks
    )

    # ── Phase 2: Fine-tune last 30 layers ──────────────────
    print("\n=== Phase 2: Fine-tune last 30 layers ===")
    base_model.trainable = True
    for layer in base_model.layers[:-30]:
        layer.trainable = False

    model.compile(
        optimizer=tf.keras.optimizers.Adam(1e-5),
        loss='sparse_categorical_crossentropy',
        metrics=['accuracy']
    )

    history2 = model.fit(
        train_ds,
        validation_data=valid_ds,
        epochs=20,
        class_weight=class_weights,
        callbacks=callbacks
    )

    # ── Combine histories ───────────────────────────────────
    combined_acc     = history1.history['accuracy']     + history2.history['accuracy']
    combined_valacc  = history1.history['val_accuracy'] + history2.history['val_accuracy']
    combined_loss    = history1.history['loss']         + history2.history['loss']
    combined_valloss = history1.history['val_loss']     + history2.history['val_loss']

    best_epoch   = int(np.argmax(combined_valacc) + 1)
    total_epochs = len(combined_acc)

    # ── Log params ──────────────────────────────────────────
    mlflow.log_param("model_name",        "ResNet50V2")
    mlflow.log_param("data_version",      "V3_Clean")
    mlflow.log_param("train_images",      train_count)
    mlflow.log_param("valid_images",      valid_count)
    mlflow.log_param("test_images",       test_count)
    mlflow.log_param("batch_size",        BATCH_SIZE)
    mlflow.log_param("epochs_run",        best_epoch)
    mlflow.log_param("total_epochs",      total_epochs)
    mlflow.log_param("optimizer",         "Adam")
    mlflow.log_param("learning_rate",     "1e-3 → 1e-5")
    mlflow.log_param("dropout",           "0.5/0.3")
    mlflow.log_param("l2_reg",            "None")
    mlflow.log_param("aug_variants",      18)
    mlflow.log_param("split",             "80_10_10")
    mlflow.log_param("class_weights",     "balanced+Bottom×1.5")
    mlflow.log_param("fine_tune_layers",  30)
    mlflow.log_param("backbone",          "ResNet50V2")

    # Log per epoch metrics
    for ep, (a, v) in enumerate(zip(combined_acc, combined_valacc)):
        mlflow.log_metric("train_accuracy", a, step=ep)
        mlflow.log_metric("val_accuracy",   v, step=ep)
    for ep, (a, v) in enumerate(zip(combined_loss, combined_valloss)):
        mlflow.log_metric("train_loss", a, step=ep)
        mlflow.log_metric("val_loss",   v, step=ep)

    # ── Evaluate ────────────────────────────────────────────
    test_loss, test_acc = model.evaluate(test_ds, verbose=0)

    y_true, y_pred = [], []
    for images, lbls in test_ds:
        preds = model.predict(images, verbose=0)
        y_true.extend(lbls.numpy())
        y_pred.extend(np.argmax(preds, axis=1))

    report = classification_report(
        y_true, y_pred, target_names=CLASS_NAMES, output_dict=True)
    cm = confusion_matrix(y_true, y_pred)

    print(f"\nTest Accuracy : {test_acc:.2%}")
    print(f"Test Loss     : {test_loss:.4f}")
    print(f"Best Epoch    : {best_epoch}/{total_epochs}")
    print("\nConfusion Matrix:\n", cm)
    print("\n", classification_report(y_true, y_pred, target_names=CLASS_NAMES))

    # Log test metrics
    mlflow.log_metric("test_accuracy", test_acc)
    mlflow.log_metric("test_loss",     test_loss)
    mlflow.log_metric("macro_f1",      report['macro avg']['f1-score'])
    for cls in CLASS_NAMES:
        mlflow.log_metric(f"{cls}_f1",        report[cls]['f1-score'])
        mlflow.log_metric(f"{cls}_precision",  report[cls]['precision'])
        mlflow.log_metric(f"{cls}_recall",     report[cls]['recall'])

    # ── Confusion matrix plot ───────────────────────────────
    fig, ax = plt.subplots(figsize=(6, 5))
    im = ax.imshow(cm, cmap='Blues')
    ax.set_xticks(range(len(CLASS_NAMES)))
    ax.set_yticks(range(len(CLASS_NAMES)))
    ax.set_xticklabels(CLASS_NAMES, rotation=45)
    ax.set_yticklabels(CLASS_NAMES)
    for i in range(len(CLASS_NAMES)):
        for j in range(len(CLASS_NAMES)):
            ax.text(j, i, cm[i,j], ha='center', va='center', fontsize=12,
                    color='white' if cm[i,j] > cm.max()/2 else 'black')
    ax.set_xlabel('Predicted'); ax.set_ylabel('Actual')
    ax.set_title('ResNet50V2 — Confusion Matrix')
    plt.colorbar(im, ax=ax)
    plt.tight_layout()
    plt.savefig("/tmp/resnet50v2_cm.png", dpi=150)
    mlflow.log_artifact("/tmp/resnet50v2_cm.png", "plots")
    plt.show()

    # ── History plot ────────────────────────────────────────
    fig, axes = plt.subplots(1, 2, figsize=(14, 5))
    phase1_end = len(history1.history['accuracy']) - 1

    axes[0].plot(combined_acc,    label='Train', color='blue')
    axes[0].plot(combined_valacc, label='Val',   color='orange')
    axes[0].axvline(x=phase1_end, color='red', linestyle='--',
                    alpha=0.6, label='Fine-tune start')
    axes[0].set_title('ResNet50V2 — Accuracy')
    axes[0].set_xlabel('Epoch'); axes[0].legend()

    axes[1].plot(combined_loss,    label='Train', color='blue')
    axes[1].plot(combined_valloss, label='Val',   color='orange')
    axes[1].axvline(x=phase1_end, color='red', linestyle='--',
                    alpha=0.6, label='Fine-tune start')
    axes[1].set_title('ResNet50V2 — Loss')
    axes[1].set_xlabel('Epoch'); axes[1].legend()

    plt.tight_layout()
    plt.savefig("/tmp/resnet50v2_history.png", dpi=150)
    mlflow.log_artifact("/tmp/resnet50v2_history.png", "plots")
    plt.show()

    # Save model
    model.save("/content/drive/MyDrive/ResNet50V2_Clean.keras")
    mlflow.log_artifact("/content/drive/MyDrive/ResNet50V2_Clean.keras", "models")

    print(f"\n✅ ResNet50V2 logged to MLflow!")
    print(f"   Test Accuracy : {test_acc:.2%}")
    print(f"   Macro F1      : {report['macro avg']['f1-score']:.2%}")
    print(f"   Best Epoch    : {best_epoch}/{total_epochs}")
    print(f"   Bottom F1     : {report['Bottom']['f1-score']:.2%}")



