axes[0,1].legend(fontsize=9)
for i, v in enumerate(df["Macro F1 %"]):
    axes[0,1].text(v+0.5, i, f"{v}%", va='center', fontsize=9)

# 3. Per-class F1
x = np.arange(len(models))
w = 0.2
for j, (cls, col) in enumerate(zip(
        ["Bottom F1","Left F1","Right F1","Top F1"],
        ['#e74c3c','#3498db','#2ecc71','#f39c12'])):
    bars = axes[1,0].bar(x+j*w, df[cls], w,
                         label=cls.replace(" F1",""), color=col)
    for bar in bars:
        h = bar.get_height()
        axes[1,0].text(bar.get_x()+bar.get_width()/2,
                       h+1, f"{h:.0f}", ha='center', fontsize=6)
axes[1,0].set_xticks(x+w*1.5)
axes[1,0].set_xticklabels(models, rotation=25, ha='right', fontsize=8)
axes[1,0].set_title("Per-Class F1 (%)", fontweight='bold')
axes[1,0].set_ylim(0, 120)
axes[1,0].axhline(y=80, color='gray', linestyle='--', alpha=0.5, label='80% line')
axes[1,0].legend()

# 4. Accuracy vs Loss
axes[1,1].scatter(df["Loss"], df["Accuracy %"],
                  c=colors, s=300, zorder=5, edgecolors='black')
for _, row in df.iterrows():
    axes[1,1].annotate(row["Model"],
        (row["Loss"], row["Accuracy %"]),
        textcoords="offset points", xytext=(6,4), fontsize=8)
axes[1,1].set_xlabel("Test Loss (lower=better)")
axes[1,1].set_ylabel("Test Accuracy (%)")
axes[1,1].set_title("Accuracy vs Loss\n(top-left = best)", fontweight='bold')
axes[1,1].axhline(y=80, color='green', linestyle='--', alpha=0.4, label='80% target')
axes[1,1].legend(fontsize=9)

plt.tight_layout()
plt.savefig('/content/drive/MyDrive/model_dashboard_final.png',
            bbox_inches='tight', dpi=150)
plt.show()

