# ── 2. Generate HTML table ──────────────────────────────────
def make_cell(val, is_metric=False):
    try:
        v = float(val)
        if is_metric:
            if v >= 80:   bg = "#27ae60"
            elif v >= 73: bg = "#f39c12"
            else:         bg = "#e74c3c"
            return f'<td style="background:{bg};color:white;font-weight:bold;text-align:center;padding:8px">{val}</td>'
    except: pass
    return f'<td style="text-align:center;padding:8px">{val}</td>'

medals = ["🥇","🥈","🥉","4th","5th","6th","7th","8th","9th"]

html = """<!DOCTYPE html><html><head><style>
  body  {font-family:Arial;margin:20px}
  table {border-collapse:collapse;width:100%;font-size:13px}
  th    {background:#2c3e50;color:white;padding:10px;text-align:center}
  tr:nth-child(even){background:#f8f9fa}
  tr:hover{background:#e8f4fd}
  .title  {font-size:22px;font-weight:bold;text-align:center;
            padding:15px;background:#2c3e50;color:white;margin-bottom:10px}
  .section{font-size:15px;font-weight:bold;background:#34495e;
            color:white;padding:8px;text-align:center;margin-top:20px}
  .best   {background:#27ae60;color:white;padding:15px;border-radius:8px;
            text-align:center;margin-top:15px;font-size:15px}
</style></head><body>
<div class="title">🏆 Model Comparison — Capacitor Orientation</div>
<table>
<tr>
  <th>Rank</th><th>Model</th>
  <th>Accuracy %</th><th>Macro F1 %</th><th>Loss</th>
  <th>Epochs</th><th>Train Images</th><th>Batch</th>
  <th>Dropout</th><th>L2</th><th>Aug</th><th>Split</th>
</tr>"""

for i, row in df.iterrows():
    m = medals[i] if i < len(medals) else str(i+1)
    html += f"<tr><td style='text-align:center;font-weight:bold;padding:8px'>{m}</td>"
    html += f"<td style='text-align:center;font-weight:bold;padding:8px'>{row['Model']}</td>"
    for col, metric in [
        ("Accuracy %",True),("Macro F1 %",True),("Loss",False),
        ("Epochs",False),("Train Images",False),("Batch",False),
        ("Dropout",False),("L2",False),("Aug",False),("Split",False)
    ]:
        html += make_cell(row[col], metric)
    html += "</tr>"
html += "</table>"

html += """<div class="section">📊 Per-Class F1 Scores (%)</div>
<table><tr>
  <th>Rank</th><th>Model</th>
  <th>Bottom F1</th><th>Left F1</th><th>Right F1</th><th>Top F1</th>
</tr>"""
for i, row in df.iterrows():
    m = medals[i] if i < len(medals) else str(i+1)
    html += f"<tr><td style='text-align:center;font-weight:bold;padding:8px'>{m}</td>"
    html += f"<td style='text-align:center;font-weight:bold;padding:8px'>{row['Model']}</td>"
    for col in ["Bottom F1","Left F1","Right F1","Top F1"]:
        html += make_cell(row[col], True)
    html += "</tr>"
html += "</table>"

best = df.iloc[0]
html += f"""
<div class="best">
  <b>🥇 BEST MODEL: {best['Model']}</b><br>
  Accuracy: {best['Accuracy %']}% &nbsp;|&nbsp;
  Macro F1: {best['Macro F1 %']}% &nbsp;|&nbsp;
  Loss: {best['Loss']} &nbsp;|&nbsp;
  Epochs: {best['Epochs']} &nbsp;|&nbsp;
  Train Images: {best['Train Images']}
</div>
</body></html>"""

HTML_PATH = "/tmp/model_comparison_table.html"
with open(HTML_PATH, "w") as f:
    f.write(html)

# ── 3. Copy both to Drive ───────────────────────────────────
shutil.copy(PNG_PATH,  "/content/drive/MyDrive/model_comparison_dashboard.png")
shutil.copy(HTML_PATH, "/content/drive/MyDrive/model_comparison_table.html")

