with mlflow.start_run(run_name="MODEL_COMPARISON_DASHBOARD"):

    # ── Log best model summary metrics ─────────────────────
    best = df.iloc[0]
    mlflow.log_metric("best_accuracy",  best["Accuracy %"])
    mlflow.log_metric("best_macro_f1",  best["Macro F1 %"])
    mlflow.log_metric("best_loss",      best["Loss"])
    mlflow.log_param("best_model",      best["Model"])
    mlflow.log_param("total_models_compared", len(df))

    # ── Log each model's metrics as named metrics ───────────
    for _, row in df.iterrows():
        name = row["Model"].replace(".", "_")
        mlflow.log_metric(f"{name}_accuracy",  row["Accuracy %"])
        mlflow.log_metric(f"{name}_macro_f1",  row["Macro F1 %"])
        mlflow.log_metric(f"{name}_loss",       row["Loss"])
        mlflow.log_metric(f"{name}_bottom_f1",  row["Bottom F1"])
        mlflow.log_metric(f"{name}_left_f1",    row["Left F1"])
        mlflow.log_metric(f"{name}_right_f1",   row["Right F1"])
        mlflow.log_metric(f"{name}_top_f1",     row["Top F1"])

    # ── Log dashboard chart as artifact ────────────────────
    mlflow.log_artifact(CHART_PATH,  "dashboard")

    # ── Log CSV table as artifact ───────────────────────────
    mlflow.log_artifact(CSV_PATH,    "dashboard")

    # ── Log an HTML version of the table ───────────────────
