import os
os.environ["MLFLOW_ALLOW_FILE_STORE"] = "true"

import mlflow
import mlflow.keras
import tensorflow as tf

MLFLOW_PATH = "/content/drive/MyDrive/mlruns"
mlflow.set_tracking_uri(f"file://{MLFLOW_PATH}")

# ───────────────────────────────────────────────
# FILL THIS IN: (run_id, keras_file_path) pairs
# ───────────────────────────────────────────────
MODEL_MAP = [
    {
        "run_name": "MobileNetV2_DataV3_Clean",  # just for your reference/logging
        "run_id": "6dbcc5bd44744424822f4c2b5b85b9c0",
        "keras_path": "/content/drive/MyDrive/PCB_AI_Model_Backup/MobileNetV2_best.keras"
    },
    {
        "run_name": "EfficientNetB0_DataV3_Clean",
        "run_id": "3efd4c39460a4cc4ab6e9d3f10604cf2",
        "keras_path": "/content/drive/MyDrive/EfficientNetB0_Clean.keras"
    },
    {
        "run_name": "MobileNetV3_DataV3_Clean",
        "run_id": "96d053e0ac0f4d94921c0b0f141d21dc",
        "keras_path": "/content/drive/MyDrive/MobileNetV3_Clean.keras"
    },
    {
        "run_name": "CNN_V1_DataV3_Clean",
        "run_id": "7f88b9aa02434710be678815e61a9716",
        "keras_path": "/content/drive/MyDrive/best_model.keras"
    },
    # add more rows here, same structure
]

# ───────────────────────────────────────────────
# Run the back-fill
# ───────────────────────────────────────────────
results = []

for entry in MODEL_MAP:
    name = entry["run_name"]
    run_id = entry["run_id"]
    path = entry["keras_path"]

    print(f"\nProcessing: {name}")

    if not os.path.exists(path):
        print(f"  ❌ File not found: {path} — skipping")
        results.append((name, "FILE_NOT_FOUND"))
        continue

    if not run_id or run_id == "PASTE_RUN_ID_HERE":
        print(f"  ❌ run_id not filled in — skipping")
        results.append((name, "NO_RUN_ID"))
        continue

    try:
        model = tf.keras.models.load_model(path)
        with mlflow.start_run(run_id=run_id):
            mlflow.keras.log_model(model, "model")
        print(f"  ✅ Attached successfully")
        results.append((name, "SUCCESS"))
    except Exception as e:
        print(f"  ❌ Failed: {e}")
        results.append((name, f"ERROR: {e}"))

# ───────────────────────────────────────────────
# Summary
# ───────────────────────────────────────────────
print("\n" + "=" * 50)
print("SUMMARY")
print("=" * 50)
for name, status in results:
    print(f"{name}: {status}")

