import os
import mlflow

os.environ["MLFLOW_ALLOW_FILE_STORE"] = "true"

mlflow.set_tracking_uri("file:///content/drive/MyDrive/mlruns")

mlflow.set_experiment("Capacitor_Polarity_Detection")

with mlflow.start_run(run_name="PCB_AI_FINAL_DELIVERABLES"):

    # Project metadata
    mlflow.log_param("project", "PCB_AI")
    mlflow.log_param("task", "Capacitor Polarity Detection")
    mlflow.log_param("final_models", 7)
    mlflow.log_param("best_models", 5)
    mlflow.log_param("experimental_models", 5)

    base = "/content/drive/MyDrive"

    # ---------- Final Models ----------
    final_models = [
        "CNN_V1_Clean.keras",
        "CNN_V2_Clean.keras",
        "CNN_V3_Clean.keras",
        "EfficientNetB0_Clean.keras",
        "MobileNetV2_Clean.keras",
        "MobileNetV3_Clean.keras",
        "ResNet50V2_Clean.keras"
    ]

    for f in final_models:
        mlflow.log_artifact(os.path.join(base, f), "models/final_models")

    # ---------- Best Models ----------
    best_models = [
        "EfficientNetB0_best.keras",
        "MobileNetV2_best.keras",
        "ResNet50V2_best.keras",
        "best_capacitor_cnn.keras",
        "best_model.keras"
    ]

    for f in best_models:
        mlflow.log_artifact(os.path.join(base, f), "models/best_models")

    # ---------- Experimental Models ----------
    experimental_models = [
        "efficientnetb0_fullaug.keras",
        "efficientnetb0_v2_clean.keras",
        "mobilenet_193_dataset.keras",
        "mobilenet_frozen.keras",
        "mobilenet_frozen_76.keras"
    ]

    for f in experimental_models:
        mlflow.log_artifact(os.path.join(base, f), "models/experimental_models")

    # ---------- Dashboards ----------
    dashboards = [
        "model_dashboard.png",
        "model_dashboard_final.png",
        "model_comparison_dashboard.png",
        "training_history.png",
        "cm_efficientnetb0_fullaug.png",
        "cm_efficientnetb0_v2.png",
        "dataset_distribution.png"
    ]

    for f in dashboards:
        mlflow.log_artifact(os.path.join(base, f), "dashboards")

    # ---------- Tables ----------
    tables = [
        "dataset.csv",
        "model_comparison.csv",
        "model_comparison_table.csv"
    ]

    for f in tables:
        mlflow.log_artifact(os.path.join(base, f), "tables")

    print("✅ PCB_AI_FINAL_DELIVERABLES logged successfully!")

